00056 InterPrediction::InterPrediction()
00057 :
00058   m_currChromaFormat( NUM_CHROMA_FORMAT )
00059 , m_maxCompIDToPred ( MAX_NUM_COMPONENT )
00060 , m_pcRdCost        ( nullptr )
00061 , m_storedMv        ( nullptr )
00062 , m_skipPROF (false)
00063 , m_encOnly  (false)
00064 , m_isBi     (false)
00065 , m_gradX0(nullptr)
00066 , m_gradY0(nullptr)
00067 , m_gradX1(nullptr)
00068 , m_gradY1(nullptr)
00069 , m_subPuMC(false)
00070 , m_IBCBufferWidth(0)
00071 {
00072   for( uint32_t ch = 0; ch < MAX_NUM_COMPONENT; ch++ )
