00106 void InterPrediction::destroy()
00107 {
00108   for( uint32_t i = 0; i < NUM_REF_PIC_LIST_01; i++ )
00109   {
00110     for( uint32_t c = 0; c < MAX_NUM_COMPONENT; c++ )
00111     {
00112       xFree( m_acYuvPred[i][c] );
00113       m_acYuvPred[i][c] = nullptr;
00114     }
00115   }
00116 
00117   for( uint32_t c = 0; c < MAX_NUM_COMPONENT; c++ )
00118   {
00119     for( uint32_t i = 0; i < LUMA_INTERPOLATION_FILTER_SUB_SAMPLE_POSITIONS_SIGNAL; i++ )
00120     {
00121       for( uint32_t j = 0; j < LUMA_INTERPOLATION_FILTER_SUB_SAMPLE_POSITIONS_SIGNAL; j++ )
00122       {
00123         xFree( m_filteredBlock[i][j][c] );
00124         m_filteredBlock[i][j][c] = nullptr;
00125       }
00126 
00127       xFree( m_filteredBlockTmp[i][c] );
00128       m_filteredBlockTmp[i][c] = nullptr;
00129     }
00130   }
00131 
00132   m_geoPartBuf[0].destroy();
00133   m_geoPartBuf[1].destroy();
00134   m_colorTransResiBuf[0].destroy();
00135   m_colorTransResiBuf[1].destroy();
00136   m_colorTransResiBuf[2].destroy();
00137 
00138   if (m_storedMv != nullptr)
00139   {
00140     delete[]m_storedMv;
00141     m_storedMv = nullptr;
00142   }
00143 
00144   xFree(m_gradX0);   m_gradX0 = nullptr;
00145   xFree(m_gradY0);   m_gradY0 = nullptr;
00146   xFree(m_gradX1);   m_gradX1 = nullptr;
00147   xFree(m_gradY1);   m_gradY1 = nullptr;
00148   xFree(m_cYuvPredTempDMVRL0);
00149   m_cYuvPredTempDMVRL0 = nullptr;
00150   xFree(m_cYuvPredTempDMVRL1);
00151   m_cYuvPredTempDMVRL1 = nullptr;
00152   for (uint32_t ch = 0; ch < MAX_NUM_COMPONENT; ch++)
00153   {
00154     xFree(m_cRefSamplesDMVRL0[ch]);
00155     m_cRefSamplesDMVRL0[ch] = nullptr;
00156     xFree(m_cRefSamplesDMVRL1[ch]);
00157     m_cRefSamplesDMVRL1[ch] = nullptr;
00158   }
00159   m_IBCBuffer.destroy();
00160 }
