00247 bool InterPrediction::xCheckIdenticalMotion( const PredictionUnit &pu )
00248 {
00249   const Slice &slice = *pu.cs->slice;
00250 
00251   if( slice.isInterB() && !pu.cs->pps->getWPBiPred() )
00252   {
00253     if( pu.refIdx[0] >= 0 && pu.refIdx[1] >= 0 )
00254     {
00255       int RefPOCL0 = slice.getRefPic( REF_PIC_LIST_0, pu.refIdx[0] )->getPOC();
00256       int RefPOCL1 = slice.getRefPic( REF_PIC_LIST_1, pu.refIdx[1] )->getPOC();
00257 
00258       if( RefPOCL0 == RefPOCL1 )
00259       {
00260         if( !pu.cu->affine )
00261         {
00262           if( pu.mv[0] == pu.mv[1] )
00263           {
00264             return true;
00265           }
00266         }
00267         else
00268         {
00269           if ( (pu.cu->affineType == AFFINEMODEL_4PARAM && (pu.mvAffi[0][0] == pu.mvAffi[1][0]) && (pu.mvAffi[0][1] == pu.mvAffi[1][1]))
00270             || (pu.cu->affineType == AFFINEMODEL_6PARAM && (pu.mvAffi[0][0] == pu.mvAffi[1][0]) && (pu.mvAffi[0][1] == pu.mvAffi[1][1]) && (pu.mvAffi[0][2] == pu.mvAffi[1][2])) )
00271           {
00272             return true;
00273           }
00274         }
00275       }
00276     }
00277   }
00278 
00279   return false;
00280 }
00281 
00282 void InterPrediction::xSubPuMC( PredictionUnit& pu, PelUnitBuf& predBuf, const RefPicList &eRefPicList /*= REF_PIC_LIST_X*/, const bool luma /*= true*/, const bool chroma /*= true*/)
00283 {
00284 
00285   // compute the location of the current PU
00286   Position puPos    = pu.lumaPos();
00287   Size puSize       = pu.lumaSize();
00288 
00289   int numPartLine, numPartCol, puHeight, puWidth;
00290   {
00291     numPartLine = std::max(puSize.width >> ATMVP_SUB_BLOCK_SIZE, 1u);
00292     numPartCol = std::max(puSize.height >> ATMVP_SUB_BLOCK_SIZE, 1u);
00293     puHeight = numPartCol == 1 ? puSize.height : 1 << ATMVP_SUB_BLOCK_SIZE;
00294     puWidth = numPartLine == 1 ? puSize.width : 1 << ATMVP_SUB_BLOCK_SIZE;
00295   }
00296 
00297   PredictionUnit subPu;
00298 
00299   subPu.cs        = pu.cs;
00300   subPu.cu        = pu.cu;
00301   subPu.mergeType = MRG_TYPE_DEFAULT_N;
00302 
00303   bool isAffine = pu.cu->affine;
00304   subPu.cu->affine = false;
00305 
00306   // join sub-pus containing the same motion
00307   bool verMC = puSize.height > puSize.width;
00308   int  fstStart = (!verMC ? puPos.y : puPos.x);
00309   int  secStart = (!verMC ? puPos.x : puPos.y);
00310   int  fstEnd = (!verMC ? puPos.y + puSize.height : puPos.x + puSize.width);
00311   int  secEnd = (!verMC ? puPos.x + puSize.width : puPos.y + puSize.height);
00312   int  fstStep = (!verMC ? puHeight : puWidth);
00313   int  secStep = (!verMC ? puWidth : puHeight);
00314 
00315   bool scaled = pu.cu->slice->getRefPic( REF_PIC_LIST_0, 0 )->isRefScaled( pu.cs->pps ) || ( pu.cs->slice->getSliceType() == B_SLICE ? pu.cu->slice->getRefPic( REF_PIC_LIST_1, 0 )->isRefScaled( pu.cs->pps ) : false );
00316 
00317   m_subPuMC = true;
00318 
00319   for (int fstDim = fstStart; fstDim < fstEnd; fstDim += fstStep)
00320   {
00321     for (int secDim = secStart; secDim < secEnd; secDim += secStep)
00322     {
00323       int x = !verMC ? secDim : fstDim;
00324       int y = !verMC ? fstDim : secDim;
00325       const MotionInfo &curMi = pu.getMotionInfo(Position{ x, y });
00326 
00327       int length = secStep;
00328       int later  = secDim + secStep;
00329 
00330       while (later < secEnd)
00331       {
00332         const MotionInfo &laterMi = !verMC ? pu.getMotionInfo(Position{ later, fstDim }) : pu.getMotionInfo(Position{ fstDim, later });
00333         if (!scaled && laterMi == curMi)
00334         {
00335           length += secStep;
00336         }
00337         else
00338         {
00339           break;
00340         }
00341         later += secStep;
00342       }
00343       int dx = !verMC ? length : puWidth;
00344       int dy = !verMC ? puHeight : length;
00345 
00346       subPu.UnitArea::operator=(UnitArea(pu.chromaFormat, Area(x, y, dx, dy)));
00347       subPu = curMi;
00348       PelUnitBuf subPredBuf = predBuf.subBuf(UnitAreaRelative(pu, subPu));
00349       subPu.mmvdEncOptMode = 0;
00350       subPu.mvRefine = false;
00351       motionCompensation(subPu, subPredBuf, eRefPicList, luma, chroma);
00352       secDim = later - secStep;
00353     }
00354   }
00355   m_subPuMC = false;
00356 
00357   pu.cu->affine = isAffine;
00358 }
00359 
00360 void InterPrediction::xSubPuBio(PredictionUnit& pu, PelUnitBuf& predBuf, const RefPicList &eRefPicList /*= REF_PIC_LIST_X*/, PelUnitBuf* yuvDstTmp /*= NULL*/)
00361 {
00362   // compute the location of the current PU
00363   Position puPos = pu.lumaPos();
00364   Size puSize = pu.lumaSize();
00365 
00366 #if JVET_J0090_MEMORY_BANDWITH_MEASURE
00367   JVET_J0090_SET_CACHE_ENABLE(true);
00368   int mvShift = (MV_FRACTIONAL_BITS_INTERNAL);
00369   for (int k = 0; k < NUM_REF_PIC_LIST_01; k++)
00370   {
00371     RefPicList refId = (RefPicList)k;
00372     const Picture* refPic = pu.cu->slice->getRefPic(refId, pu.refIdx[refId]);
00373     for (int compID = 0; compID < MAX_NUM_COMPONENT; compID++)
00374     {
00375       Mv cMv = pu.mv[refId];
00376       int mvshiftTemp = mvShift + getComponentScaleX((ComponentID)compID, pu.chromaFormat);
00377       int filtersize = (compID == (COMPONENT_Y)) ? NTAPS_LUMA : NTAPS_CHROMA;
00378       cMv += Mv(-(((filtersize >> 1) - 1) << mvshiftTemp), -(((filtersize >> 1) - 1) << mvshiftTemp));
00379       bool wrapRef = false;
00380       if ( pu.cu->slice->getRefPic(refId, pu.refIdx[refId])->isWrapAroundEnabled( pu.cs->pps ) )
00381       {
00382         wrapRef = wrapClipMv(cMv, pu.blocks[0].pos(), pu.blocks[0].size(), pu.cs->sps, pu.cs->pps);
00383       }
00384       else
00385       {
00386         clipMv(cMv, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps);
00387       }
00388 
00389       int width = predBuf.bufs[compID].width + (filtersize - 1);
00390       int height = predBuf.bufs[compID].height + (filtersize - 1);
00391 
00392       CPelBuf refBuf;
00393       Position recOffset = pu.blocks[compID].pos().offset(cMv.getHor() >> mvshiftTemp, cMv.getVer() >> mvshiftTemp);
00394       refBuf = refPic->getRecoBuf(CompArea((ComponentID)compID, pu.chromaFormat, recOffset, pu.blocks[compID].size()), wrapRef);
00395 
00396       JVET_J0090_SET_REF_PICTURE(refPic, (ComponentID)compID);
00397       for (int row = 0; row < height; row++)
00398       {
00399         for (int col = 0; col < width; col++)
00400         {
00401           JVET_J0090_CACHE_ACCESS(((Pel *)refBuf.buf) + row * refBuf.stride + col, __FILE__, __LINE__);
00402         }
00403       }
00404     }
00405   }
00406   JVET_J0090_SET_CACHE_ENABLE(false);
00407 #endif
00408   PredictionUnit subPu;
00409 
00410   subPu.cs = pu.cs;
00411   subPu.cu = pu.cu;
00412   subPu.mergeType = pu.mergeType;
00413   subPu.mmvdMergeFlag = pu.mmvdMergeFlag;
00414   subPu.mmvdEncOptMode = pu.mmvdEncOptMode;
00415   subPu.mergeFlag = pu.mergeFlag;
00416   subPu.ciipFlag = pu.ciipFlag;
00417   subPu.mvRefine = pu.mvRefine;
00418   subPu.refIdx[0] = pu.refIdx[0];
00419   subPu.refIdx[1] = pu.refIdx[1];
00420   int  fstStart = puPos.y;
00421   int  secStart = puPos.x;
00422   int  fstEnd = puPos.y + puSize.height;
00423   int  secEnd = puPos.x + puSize.width;
00424   int  fstStep = std::min((int)MAX_BDOF_APPLICATION_REGION, (int)puSize.height);
00425   int  secStep = std::min((int)MAX_BDOF_APPLICATION_REGION, (int)puSize.width);
00426   for (int fstDim = fstStart; fstDim < fstEnd; fstDim += fstStep)
00427   {
00428     for (int secDim = secStart; secDim < secEnd; secDim += secStep)
00429     {
00430       int x = secDim;
00431       int y = fstDim;
00432       int dx = secStep;
00433       int dy = fstStep;
00434 
00435       const MotionInfo &curMi = pu.getMotionInfo(Position{ x, y });
00436 
00437       subPu.UnitArea::operator=(UnitArea(pu.chromaFormat, Area(x, y, dx, dy)));
00438       subPu = curMi;
00439       PelUnitBuf subPredBuf = predBuf.subBuf(UnitAreaRelative(pu, subPu));
00440 
00441       if (yuvDstTmp)
00442       {
00443         PelUnitBuf subPredBufTmp = yuvDstTmp->subBuf(UnitAreaRelative(pu, subPu));
00444         motionCompensation(subPu, subPredBuf, eRefPicList, true, true, &subPredBufTmp);
00445       }
00446       else
00447       motionCompensation(subPu, subPredBuf, eRefPicList);
00448     }
00449   }
00450   JVET_J0090_SET_CACHE_ENABLE(true);
00451 }
00452 
00453 void InterPrediction::xPredInterUni(const PredictionUnit &pu, const RefPicList &eRefPicList, PelUnitBuf &pcYuvPred,
00454                                     const bool &bi, const bool &bioApplied, const bool luma, const bool chroma)
00455 {
00456   const SPS &sps = *pu.cs->sps;
00457 
00458   int iRefIdx = pu.refIdx[eRefPicList];
00459   Mv mv[3];
00460   bool isIBC = false;
00461   CHECK( !CU::isIBC( *pu.cu ) && pu.lwidth() == 4 && pu.lheight() == 4, "invalid 4x4 inter blocks" );
00462   if (CU::isIBC(*pu.cu))
00463   {
00464     isIBC = true;
00465   }
00466   if( pu.cu->affine )
00467   {
00468     CHECK( iRefIdx < 0, "iRefIdx incorrect." );
00469 
00470     mv[0] = pu.mvAffi[eRefPicList][0];
00471     mv[1] = pu.mvAffi[eRefPicList][1];
00472     mv[2] = pu.mvAffi[eRefPicList][2];
00473   }
00474   else
00475   {
00476     mv[0] = pu.mv[eRefPicList];
00477   }
00478 
00479   if( !pu.cu->affine )
00480   {
00481     if( !isIBC && pu.cu->slice->getRefPic( eRefPicList, iRefIdx )->isRefScaled( pu.cs->pps ) == false )
00482     {
00483       if( !pu.cs->pps->getWrapAroundEnabledFlag() )
00484       {
00485         clipMv( mv[0], pu.cu->lumaPos(), pu.cu->lumaSize(), sps, *pu.cs->pps );
00486       }
00487     }
00488   }
00489 
00490   for( uint32_t comp = COMPONENT_Y; comp < pcYuvPred.bufs.size() && comp <= m_maxCompIDToPred; comp++ )
00491   {
00492     const ComponentID compID = ComponentID( comp );
00493     if (compID == COMPONENT_Y && !luma)
00494     {
00495       continue;
00496     }
00497     if (compID != COMPONENT_Y && !chroma)
00498     {
00499       continue;
00500     }
00501     if ( pu.cu->affine )
00502     {
00503       CHECK( bioApplied, "BIO is not allowed with affine" );
00504       m_iRefListIdx = eRefPicList;
00505       bool genChromaMv = (!luma && chroma && compID == COMPONENT_Cb);
00506       xPredAffineBlk( compID, pu, pu.cu->slice->getRefPic( eRefPicList, iRefIdx )->unscaledPic, mv, pcYuvPred, bi, pu.cu->slice->clpRng( compID ), genChromaMv, pu.cu->slice->getScalingRatio( eRefPicList, iRefIdx ));
00507     }
00508     else
00509     {
00510       if (isIBC)
00511       {
00512         xPredInterBlk(compID, pu, pu.cu->slice->getPic(), mv[0], pcYuvPred, bi, pu.cu->slice->clpRng(compID),
00513                       bioApplied, isIBC);
00514       }
00515       else
00516       {
00517         xPredInterBlk( compID, pu, pu.cu->slice->getRefPic( eRefPicList, iRefIdx )->unscaledPic, mv[0], pcYuvPred, bi, pu.cu->slice->clpRng( compID ), bioApplied, isIBC, pu.cu->slice->getScalingRatio( eRefPicList, iRefIdx ) );
00518       }
00519     }
00520   }
00521 }
00522 
00523 void InterPrediction::xPredInterBi(PredictionUnit &pu, PelUnitBuf &pcYuvPred, const bool luma, const bool chroma, PelUnitBuf *yuvPredTmp /*= NULL*/)
00524 {
00525   const PPS   &pps   = *pu.cs->pps;
00526   const Slice &slice = *pu.cs->slice;
00527   CHECK( !pu.cu->affine && pu.refIdx[0] >= 0 && pu.refIdx[1] >= 0 && ( pu.lwidth() + pu.lheight() == 12 ), "invalid 4x8/8x4 bi-predicted blocks" );
00528 
00529   int refIdx0 = pu.refIdx[REF_PIC_LIST_0];
00530   int refIdx1 = pu.refIdx[REF_PIC_LIST_1];
00531 
00532   const WPScalingParam *wp0 = pu.cs->slice->getWpScaling(REF_PIC_LIST_0, refIdx0);
00533   const WPScalingParam *wp1 = pu.cs->slice->getWpScaling(REF_PIC_LIST_1, refIdx1);
00534 
00535   bool bioApplied = false;
00536   if (pu.cs->sps->getBDOFEnabledFlag() && (!pu.cs->picHeader->getBdofDisabledFlag()))
00537   {
00538     if (pu.cu->affine || m_subPuMC)
00539     {
00540       bioApplied = false;
00541     }
00542     else
00543     {
00544       const bool biocheck0 =
00545         !((WPScalingParam::isWeighted(wp0) || WPScalingParam::isWeighted(wp1)) && slice.getSliceType() == B_SLICE);
00546       const bool biocheck1 = !(pps.getUseWP() && slice.getSliceType() == P_SLICE);
00547       if (biocheck0
00548         && biocheck1
00549         && PU::isBiPredFromDifferentDirEqDistPoc(pu)
00550         && (pu.Y().height >= 8)
00551         && (pu.Y().width >= 8)
00552         && ((pu.Y().height * pu.Y().width) >= 128)
00553        )
00554       {
00555         bioApplied = true;
00556       }
00557     }
00558 
00559     if (bioApplied && pu.ciipFlag)
00560     {
00561       bioApplied = false;
00562     }
00563 
00564     if (bioApplied && pu.cu->smvdMode)
00565     {
00566       bioApplied = false;
00567     }
00568 
00569     if (pu.cu->cs->sps->getUseBcw() && bioApplied && pu.cu->BcwIdx != BCW_DEFAULT)
00570     {
00571       bioApplied = false;
00572     }
00573   }
00574   if (pu.mmvdEncOptMode == 2 && pu.mmvdMergeFlag)
00575   {
00576     bioApplied = false;
00577   }
00578   bool dmvrApplied = false;
00579   dmvrApplied = (pu.mvRefine) && PU::checkDMVRCondition(pu);
00580 
00581   bool refIsScaled = ( refIdx0 < 0 ? false : pu.cu->slice->getRefPic( REF_PIC_LIST_0, refIdx0 )->isRefScaled( pu.cs->pps ) ) ||
00582                      ( refIdx1 < 0 ? false : pu.cu->slice->getRefPic( REF_PIC_LIST_1, refIdx1 )->isRefScaled( pu.cs->pps ) );
00583   dmvrApplied = dmvrApplied && !refIsScaled;
00584   bioApplied = bioApplied && !refIsScaled;
00585 
00586   for (uint32_t refList = 0; refList < NUM_REF_PIC_LIST_01; refList++)
00587   {
00588     if( pu.refIdx[refList] < 0)
00589     {
00590       continue;
00591     }
00592 
00593     RefPicList eRefPicList = (refList ? REF_PIC_LIST_1 : REF_PIC_LIST_0);
00594 
00595     CHECK(CU::isIBC(*pu.cu) && eRefPicList != REF_PIC_LIST_0, "Invalid interdir for ibc mode");
00596     CHECK(CU::isIBC(*pu.cu) && pu.refIdx[refList] != MAX_NUM_REF, "Invalid reference index for ibc mode");
00597     CHECK((CU::isInter(*pu.cu) && pu.refIdx[refList] >= slice.getNumRefIdx(eRefPicList)), "Invalid reference index");
00598     m_iRefListIdx = refList;
00599 
00600     PelUnitBuf pcMbBuf = ( pu.chromaFormat == CHROMA_400 ?
00601                            PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[refList][0], pcYuvPred.Y())) :
00602                            PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[refList][0], pcYuvPred.Y()), PelBuf(m_acYuvPred[refList][1], pcYuvPred.Cb()), PelBuf(m_acYuvPred[refList][2], pcYuvPred.Cr())) );
00603 
00604     if (pu.refIdx[0] >= 0 && pu.refIdx[1] >= 0)
00605     {
00606       if (dmvrApplied)
00607       {
00608         if (yuvPredTmp)
00609         {
00610           xPredInterUni(pu, eRefPicList, pcMbBuf, true, false, luma, chroma);
00611         }
00612         continue;
00613       }
00614       xPredInterUni(pu, eRefPicList, pcMbBuf, true, bioApplied, luma, chroma);
00615     }
00616     else
00617     {
00618       if( ( (pps.getUseWP() && slice.getSliceType() == P_SLICE) || (pps.getWPBiPred() && slice.getSliceType() == B_SLICE) ) )
00619       {
00620         xPredInterUni(pu, eRefPicList, pcMbBuf, true, bioApplied, luma, chroma);
00621       }
00622       else
00623       {
00624         xPredInterUni(pu, eRefPicList, pcMbBuf, pu.cu->geoFlag, bioApplied, luma, chroma);
00625       }
00626     }
00627   }
00628   CPelUnitBuf srcPred0 = ( pu.chromaFormat == CHROMA_400 ?
00629                            CPelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[0][0], pcYuvPred.Y())) :
00630                            CPelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[0][0], pcYuvPred.Y()), PelBuf(m_acYuvPred[0][1], pcYuvPred.Cb()), PelBuf(m_acYuvPred[0][2], pcYuvPred.Cr())) );
00631   CPelUnitBuf srcPred1 = ( pu.chromaFormat == CHROMA_400 ?
00632                            CPelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[1][0], pcYuvPred.Y())) :
00633                            CPelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[1][0], pcYuvPred.Y()), PelBuf(m_acYuvPred[1][1], pcYuvPred.Cb()), PelBuf(m_acYuvPred[1][2], pcYuvPred.Cr())) );
00634   const bool lumaOnly   = luma && !chroma;
00635   const bool chromaOnly = !luma && chroma;
00636   if( !pu.cu->geoFlag && (!dmvrApplied) && (!bioApplied) && pps.getWPBiPred() && slice.getSliceType() == B_SLICE && pu.cu->BcwIdx == BCW_DEFAULT)
00637   {
00638     xWeightedPredictionBi( pu, srcPred0, srcPred1, pcYuvPred, m_maxCompIDToPred, lumaOnly, chromaOnly );
00639     if (yuvPredTmp)
00640     {
00641       yuvPredTmp->copyFrom(pcYuvPred);
00642     }
00643   }
00644   else if( !pu.cu->geoFlag && pps.getUseWP() && slice.getSliceType() == P_SLICE )
00645   {
00646     xWeightedPredictionUni( pu, srcPred0, REF_PIC_LIST_0, pcYuvPred, -1, m_maxCompIDToPred, lumaOnly, chromaOnly );
00647     if (yuvPredTmp)
00648     {
00649       yuvPredTmp->copyFrom(pcYuvPred);
00650     }
00651   }
00652   else
00653   {
00654     if (dmvrApplied)
00655     {
00656       if (yuvPredTmp)
00657       {
00658         yuvPredTmp->addAvg(srcPred0, srcPred1, slice.clpRngs(), false);
00659       }
00660       xProcessDMVR(pu, pcYuvPred, slice.clpRngs(), bioApplied);
00661     }
00662     else
00663     {
00664       xWeightedAverage( pu, srcPred0, srcPred1, pcYuvPred, slice.getSPS()->getBitDepths(), slice.clpRngs(), bioApplied, lumaOnly, chromaOnly, yuvPredTmp );
00665     }
00666   }
00667 }
00668 
00669 void InterPrediction::xPredInterBlk ( const ComponentID& compID, const PredictionUnit& pu, const Picture* refPic, const Mv& _mv, PelUnitBuf& dstPic, const bool& bi, const ClpRng& clpRng
00670                                      , const bool& bioApplied
00671                                      , bool isIBC
00672                                      , const std::pair<int, int> scalingRatio
00673                                      , SizeType dmvrWidth
00674                                      , SizeType dmvrHeight
00675                                      , bool bilinearMC
00676                                      , Pel *srcPadBuf
00677                                      , int32_t srcPadStride
00678                                     )
00679 {
00680   JVET_J0090_SET_REF_PICTURE( refPic, compID );
00681   const ChromaFormat  chFmt = pu.chromaFormat;
00682   const bool          rndRes = !bi;
00683 
00684   int shiftHor = MV_FRACTIONAL_BITS_INTERNAL + vtm::getComponentScaleX(compID, chFmt);
00685   int shiftVer = MV_FRACTIONAL_BITS_INTERNAL + vtm::getComponentScaleY(compID, chFmt);
00686 
00687   bool  wrapRef = false;
00688   Mv    mv(_mv);
00689   if( !isIBC && refPic->isWrapAroundEnabled( pu.cs->pps ) )
00690   {
00691     wrapRef = wrapClipMv( mv, pu.blocks[0].pos(), pu.blocks[0].size(), pu.cs->sps, pu.cs->pps );
00692   }
00693 
00694   bool useAltHpelIf = pu.cu->imv == IMV_HPEL;
00695 
00696   if( !isIBC && xPredInterBlkRPR( scalingRatio, *pu.cs->pps, CompArea( compID, chFmt, pu.blocks[compID], Size( dstPic.bufs[compID].width, dstPic.bufs[compID].height ) ), refPic, mv, dstPic.bufs[compID].buf, dstPic.bufs[compID].stride, bi, wrapRef, clpRng, 0, useAltHpelIf ) )
00697   {
00698     CHECK( bilinearMC, "DMVR should be disabled with RPR" );
00699     CHECK( bioApplied, "BDOF should be disabled with RPR" );
00700   }
00701   else
00702   {
00703     int xFrac = mv.hor & ((1 << shiftHor) - 1);
00704     int yFrac = mv.ver & ((1 << shiftVer) - 1);
00705     if (isIBC)
00706     {
00707       xFrac = yFrac = 0;
00708       JVET_J0090_SET_CACHE_ENABLE(false);
00709     }
00710 
00711     PelBuf & dstBuf = dstPic.bufs[compID];
00712     unsigned width  = dstBuf.width;
00713     unsigned height = dstBuf.height;
00714 
00715     CPelBuf refBuf;
00716     {
00717       Position offset = pu.blocks[compID].pos().offset(mv.getHor() >> shiftHor, mv.getVer() >> shiftVer);
00718       if (dmvrWidth)
00719       {
00720         refBuf = refPic->getRecoBuf(CompArea(compID, chFmt, offset, Size(dmvrWidth, dmvrHeight)), wrapRef);
00721       }
00722       else
00723       {
00724         refBuf = refPic->getRecoBuf(CompArea(compID, chFmt, offset, pu.blocks[compID].size()), wrapRef);
00725       }
00726     }
00727 
00728     if (NULL != srcPadBuf)
00729     {
00730       refBuf.buf    = srcPadBuf;
00731       refBuf.stride = srcPadStride;
00732     }
00733     if (dmvrWidth)
00734     {
00735       width  = dmvrWidth;
00736       height = dmvrHeight;
00737     }
00738     // backup data
00739     int  backupWidth        = width;
00740     int  backupHeight       = height;
00741     Pel *backupDstBufPtr    = dstBuf.buf;
00742     int  backupDstBufStride = dstBuf.stride;
00743 
00744     if (bioApplied && compID == COMPONENT_Y)
00745     {
00746       width  = width + 2 * BIO_EXTEND_SIZE + 2;
00747       height = height + 2 * BIO_EXTEND_SIZE + 2;
00748 
00749       // change MC output
00750       dstBuf.stride = width;
00751       dstBuf.buf    = m_filteredBlockTmp[2 + m_iRefListIdx][compID] + 2 * dstBuf.stride + 2;
00752     }
00753 
00754     if (yFrac == 0)
00755     {
00756       m_if.filterHor(compID, (Pel *) refBuf.buf, refBuf.stride, dstBuf.buf, dstBuf.stride, backupWidth, backupHeight,
00757                      xFrac, rndRes, chFmt, clpRng, bilinearMC, bilinearMC, useAltHpelIf);
00758     }
00759     else if (xFrac == 0)
00760     {
00761       m_if.filterVer(compID, (Pel *) refBuf.buf, refBuf.stride, dstBuf.buf, dstBuf.stride, backupWidth, backupHeight,
00762                      yFrac, true, rndRes, chFmt, clpRng, bilinearMC, bilinearMC, useAltHpelIf);
00763     }
00764     else
00765     {
00766       PelBuf tmpBuf = dmvrWidth ? PelBuf(m_filteredBlockTmp[0][compID], Size(dmvrWidth, dmvrHeight))
00767                                 : PelBuf(m_filteredBlockTmp[0][compID], pu.blocks[compID]);
00768       if (dmvrWidth == 0)
00769       {
00770         tmpBuf.stride = dstBuf.stride;
00771       }
00772 
00773       int vFilterSize = isLuma(compID) ? NTAPS_LUMA : NTAPS_CHROMA;
00774       if (bilinearMC)
00775       {
00776         vFilterSize = NTAPS_BILINEAR;
00777       }
00778       m_if.filterHor(compID, (Pel *) refBuf.buf - ((vFilterSize >> 1) - 1) * refBuf.stride, refBuf.stride, tmpBuf.buf,
00779                      tmpBuf.stride, backupWidth, backupHeight + vFilterSize - 1, xFrac, false, chFmt, clpRng,
00780                      bilinearMC, bilinearMC, useAltHpelIf);
00781       JVET_J0090_SET_CACHE_ENABLE(false);
00782       m_if.filterVer(compID, (Pel *) tmpBuf.buf + ((vFilterSize >> 1) - 1) * tmpBuf.stride, tmpBuf.stride, dstBuf.buf,
00783                      dstBuf.stride, backupWidth, backupHeight, yFrac, false, rndRes, chFmt, clpRng, bilinearMC,
00784                      bilinearMC, useAltHpelIf);
00785     }
00786     JVET_J0090_SET_CACHE_ENABLE(
00787       (srcPadStride == 0)
00788       && (bioApplied
00789           == false));   // Enabled only in non-DMVR-non-BDOF process, In DMVR process, srcPadStride is always non-zero
00790     if (bioApplied && compID == COMPONENT_Y)
00791     {
00792       const int shift = IF_INTERNAL_FRAC_BITS(clpRng.bd);
00793       int        xOffset = (xFrac < 8) ? 1 : 0;
00794       int        yOffset = (yFrac < 8) ? 1 : 0;
00795       const Pel *refPel  = refBuf.buf - yOffset * refBuf.stride - xOffset;
00796       Pel *      dstPel  = m_filteredBlockTmp[2 + m_iRefListIdx][compID] + dstBuf.stride + 1;
00797       for (int w = 0; w < (width - 2 * BIO_EXTEND_SIZE); w++)
00798       {
00799         Pel val   = leftShift_round(refPel[w], shift);
00800         dstPel[w] = val - (Pel) IF_INTERNAL_OFFS;
00801       }
00802 
00803       refPel = refBuf.buf + (1 - yOffset) * refBuf.stride - xOffset;
00804       dstPel = m_filteredBlockTmp[2 + m_iRefListIdx][compID] + 2 * dstBuf.stride + 1;
00805       for (int h = 0; h < (height - 2 * BIO_EXTEND_SIZE - 2); h++)
00806       {
00807         Pel val   = leftShift_round(refPel[0], shift);
00808         dstPel[0] = val - (Pel) IF_INTERNAL_OFFS;
00809 
00810         val               = leftShift_round(refPel[width - 3], shift);
00811         dstPel[width - 3] = val - (Pel) IF_INTERNAL_OFFS;
00812 
00813         refPel += refBuf.stride;
00814         dstPel += dstBuf.stride;
00815       }
00816 
00817       refPel = refBuf.buf + (height - 2 * BIO_EXTEND_SIZE - 2 + 1 - yOffset) * refBuf.stride - xOffset;
00818       dstPel = m_filteredBlockTmp[2 + m_iRefListIdx][compID] + (height - 2 * BIO_EXTEND_SIZE) * dstBuf.stride + 1;
00819       for (int w = 0; w < (width - 2 * BIO_EXTEND_SIZE); w++)
00820       {
00821         Pel val   = leftShift_round(refPel[w], shift);
00822         dstPel[w] = val - (Pel) IF_INTERNAL_OFFS;
00823       }
00824 
00825       // restore data
00826       width         = backupWidth;
00827       height        = backupHeight;
00828       dstBuf.buf    = backupDstBufPtr;
00829       dstBuf.stride = backupDstBufStride;
00830     }
00831   }
00832 }
00833 
00834 bool InterPrediction::isSubblockVectorSpreadOverLimit( int a, int b, int c, int d, int predType )
00835 {
00836   int s4 = ( 4 << 11 );
00837   int filterTap = 6;
00838 
00839   if ( predType == 3 )
00840   {
00841     int refBlkWidth  = std::max( std::max( 0, 4 * a + s4 ), std::max( 4 * c, 4 * a + 4 * c + s4 ) ) - std::min( std::min( 0, 4 * a + s4 ), std::min( 4 * c, 4 * a + 4 * c + s4 ) );
00842     int refBlkHeight = std::max( std::max( 0, 4 * b ), std::max( 4 * d + s4, 4 * b + 4 * d + s4 ) ) - std::min( std::min( 0, 4 * b ), std::min( 4 * d + s4, 4 * b + 4 * d + s4 ) );
00843     refBlkWidth  = ( refBlkWidth >> 11 ) + filterTap + 3;
00844     refBlkHeight = ( refBlkHeight >> 11 ) + filterTap + 3;
00845 
00846     if ( refBlkWidth * refBlkHeight > ( filterTap + 9 ) * ( filterTap + 9 ) )
00847     {
00848       return true;
00849     }
00850   }
00851   else
00852   {
00853     int refBlkWidth  = std::max( 0, 4 * a + s4 ) - std::min( 0, 4 * a + s4 );
00854     int refBlkHeight = std::max( 0, 4 * b ) - std::min( 0, 4 * b );
00855     refBlkWidth  = ( refBlkWidth >> 11 ) + filterTap + 3;
00856     refBlkHeight = ( refBlkHeight >> 11 ) + filterTap + 3;
00857     if ( refBlkWidth * refBlkHeight > ( filterTap + 9 ) * ( filterTap + 5 ) )
00858     {
00859       return true;
00860     }
00861 
00862     refBlkWidth  = std::max( 0, 4 * c ) - std::min( 0, 4 * c );
00863     refBlkHeight = std::max( 0, 4 * d + s4 ) - std::min( 0, 4 * d + s4 );
00864     refBlkWidth  = ( refBlkWidth >> 11 ) + filterTap + 3;
00865     refBlkHeight = ( refBlkHeight >> 11 ) + filterTap + 3;
00866     if ( refBlkWidth * refBlkHeight > ( filterTap + 5 ) * ( filterTap + 9 ) )
00867     {
00868       return true;
00869     }
00870   }
00871   return false;
00872 }
00873 
00874 void InterPrediction::xPredAffineBlk(const ComponentID &compID, const PredictionUnit &pu, const Picture *refPic, const Mv *_mv, PelUnitBuf &dstPic, const bool &bi, const ClpRng &clpRng, bool genChromaMv, const std::pair<int, int> scalingRatio)
00875 {
00876 
00877   JVET_J0090_SET_REF_PICTURE( refPic, compID );
00878   const ChromaFormat chFmt = pu.chromaFormat;
00879   int iScaleX = vtm::getComponentScaleX( compID, chFmt );
00880   int iScaleY = vtm::getComponentScaleY( compID, chFmt );
00881 
00882   Mv mvLT =_mv[0];
00883   Mv mvRT =_mv[1];
00884   Mv mvLB =_mv[2];
00885 
00886   // get affine sub-block width and height
00887   const int width  = pu.Y().width;
00888   const int height = pu.Y().height;
00889   int blockWidth = AFFINE_MIN_BLOCK_SIZE;
00890   int blockHeight = AFFINE_MIN_BLOCK_SIZE;
00891 
00892   CHECK(blockWidth  > (width >> iScaleX ), "Sub Block width  > Block width");
00893   CHECK(blockHeight > (height >> iScaleY), "Sub Block height > Block height");
00894   const int MVBUFFER_SIZE = MAX_CU_SIZE / MIN_PU_SIZE;
00895 
00896   const int cxWidth  = width  >> iScaleX;
00897   const int cxHeight = height >> iScaleY;
00898   const int iHalfBW  = blockWidth  >> 1;
00899   const int iHalfBH  = blockHeight >> 1;
00900 
00901   const int iBit = MAX_CU_DEPTH;
00902   int iDMvHorX, iDMvHorY, iDMvVerX, iDMvVerY;
00903   iDMvHorX = (mvRT - mvLT).getHor() << (iBit - floorLog2(cxWidth));
00904   iDMvHorY = (mvRT - mvLT).getVer() << (iBit - floorLog2(cxWidth));
00905   if ( pu.cu->affineType == AFFINEMODEL_6PARAM )
00906   {
00907     iDMvVerX = (mvLB - mvLT).getHor() << (iBit - floorLog2(cxHeight));
00908     iDMvVerY = (mvLB - mvLT).getVer() << (iBit - floorLog2(cxHeight));
00909   }
00910   else
00911   {
00912     iDMvVerX = -iDMvHorY;
00913     iDMvVerY = iDMvHorX;
00914   }
00915 
00916   int iMvScaleHor = mvLT.getHor() << iBit;
00917   int iMvScaleVer = mvLT.getVer() << iBit;
00918   const SPS &sps    = *pu.cs->sps;
00919 
00920   const int vFilterSize = isLuma(compID) ? NTAPS_LUMA : NTAPS_CHROMA;
00921 
00922   const int shift = iBit - 4 + MV_FRACTIONAL_BITS_INTERNAL;
00923   bool      wrapRef = false;
00924   const bool subblkMVSpreadOverLimit = isSubblockVectorSpreadOverLimit( iDMvHorX, iDMvHorY, iDMvVerX, iDMvVerY, pu.interDir );
00925 
00926   bool enablePROF = (sps.getUsePROF()) && (!m_skipPROF) && (compID == COMPONENT_Y);
00927   enablePROF &= (!pu.cs->picHeader->getProfDisabledFlag());
00928   enablePROF &= !((pu.cu->affineType == AFFINEMODEL_6PARAM && _mv[0] == _mv[1] && _mv[0] == _mv[2]) || (pu.cu->affineType == AFFINEMODEL_4PARAM && _mv[0] == _mv[1]));
00929   enablePROF &= !subblkMVSpreadOverLimit;
00930   const int profThres = 1 << (iBit + (m_isBi ? 1 : 0));
00931   enablePROF &= !m_encOnly || pu.cu->slice->getCheckLDC() || iDMvHorX > profThres || iDMvHorY > profThres || iDMvVerX > profThres || iDMvVerY > profThres || iDMvHorX < -profThres || iDMvHorY < -profThres || iDMvVerX < -profThres || iDMvVerY < -profThres;
00932   enablePROF &= (refPic->isRefScaled( pu.cs->pps ) == false);
00933 
00934   bool isLast = enablePROF ? false : !bi;
00935 
00936   const int cuExtW = AFFINE_MIN_BLOCK_SIZE + PROF_BORDER_EXT_W * 2;
00937   const int cuExtH = AFFINE_MIN_BLOCK_SIZE + PROF_BORDER_EXT_H * 2;
00938 
00939   PelBuf gradXExt(m_gradBuf[0], cuExtW, cuExtH);
00940   PelBuf gradYExt(m_gradBuf[1], cuExtW, cuExtH);
00941   const int MAX_FILTER_SIZE = std::max<int>(NTAPS_LUMA, NTAPS_CHROMA);
00942   const int dstExtW = ((blockWidth + PROF_BORDER_EXT_W * 2 + 7) >> 3) << 3;
00943   const int dstExtH = blockHeight + PROF_BORDER_EXT_H * 2;
00944   PelBuf dstExtBuf(m_filteredBlockTmp[1][compID], dstExtW, dstExtH);
00945 
00946   const int refExtH = dstExtH + MAX_FILTER_SIZE - 1;
00947   PelBuf tmpBuf = PelBuf(m_filteredBlockTmp[0][compID], dstExtW, refExtH);
00948 
00949   PelBuf &dstBuf = dstPic.bufs[compID];
00950 
00951   int *dMvScaleHor = m_dMvBuf[m_iRefListIdx];
00952   int *dMvScaleVer = m_dMvBuf[m_iRefListIdx] + 16;
00953 
00954   if (enablePROF)
00955   {
00956     int* dMvH = dMvScaleHor;
00957     int* dMvV = dMvScaleVer;
00958     int quadHorX = iDMvHorX << 2;
00959     int quadHorY = iDMvHorY << 2;
00960     int quadVerX = iDMvVerX << 2;
00961     int quadVerY = iDMvVerY << 2;
00962 
00963     dMvH[0] = ((iDMvHorX + iDMvVerX) << 1) - ((quadHorX + quadVerX) << 1);
00964     dMvV[0] = ((iDMvHorY + iDMvVerY) << 1) - ((quadHorY + quadVerY) << 1);
00965 
00966     for (int w = 1; w < blockWidth; w++)
00967     {
00968       dMvH[w] = dMvH[w - 1] + quadHorX;
00969       dMvV[w] = dMvV[w - 1] + quadHorY;
00970     }
00971 
00972     dMvH += blockWidth;
00973     dMvV += blockWidth;
00974     for (int h = 1; h < blockHeight; h++)
00975     {
00976       for (int w = 0; w < blockWidth; w++)
00977       {
00978         dMvH[w] = dMvH[w - blockWidth] + quadVerX;
00979         dMvV[w] = dMvV[w - blockWidth] + quadVerY;
00980       }
00981       dMvH += blockWidth;
00982       dMvV += blockWidth;
00983     }
00984 
00985     const int mvShift  = 8;
00986     const int dmvLimit = ( 1 << 5 ) - 1;
00987 
00988     if (!g_pelBufOP.roundIntVector)
00989     {
00990       for (int idx = 0; idx < blockWidth * blockHeight; idx++)
00991       {
00992         roundAffineMv(dMvScaleHor[idx], dMvScaleVer[idx], mvShift);
00993         dMvScaleHor[idx] = Clip3( -dmvLimit, dmvLimit, dMvScaleHor[idx] );
00994         dMvScaleVer[idx] = Clip3( -dmvLimit, dmvLimit, dMvScaleVer[idx] );
00995       }
00996     }
00997     else
00998     {
00999       int sz = blockWidth * blockHeight;
01000       g_pelBufOP.roundIntVector(dMvScaleHor, sz, mvShift, dmvLimit);
01001       g_pelBufOP.roundIntVector(dMvScaleVer, sz, mvShift, dmvLimit);
01002     }
01003   }
01004   int scaleXLuma = vtm::getComponentScaleX(COMPONENT_Y, chFmt);
01005   int scaleYLuma = vtm::getComponentScaleY(COMPONENT_Y, chFmt);
01006 
01007   if (genChromaMv && pu.chromaFormat != CHROMA_444)
01008   {
01009     CHECK(compID == COMPONENT_Y, "Chroma only subblock MV calculation should not apply to Luma");
01010     int lumaBlockWidth  = AFFINE_MIN_BLOCK_SIZE;
01011     int lumaBlockHeight = AFFINE_MIN_BLOCK_SIZE;
01012 
01013     CHECK(lumaBlockWidth > (width >> scaleXLuma), "Sub Block width  > Block width");
01014     CHECK(lumaBlockHeight > (height >> scaleYLuma), "Sub Block height > Block height");
01015 
01016     const int cxWidthLuma  = width >> scaleXLuma;
01017     const int cxHeightLuma = height >> scaleYLuma;
01018     const int halfBWLuma  = lumaBlockWidth >> 1;
01019     const int halfBHLuma  = lumaBlockHeight >> 1;
01020 
01021     int dMvHorXLuma, dMvHorYLuma, dMvVerXLuma, dMvVerYLuma;
01022     dMvHorXLuma = (mvRT - mvLT).getHor() << (iBit - floorLog2(cxWidthLuma));
01023     dMvHorYLuma = (mvRT - mvLT).getVer() << (iBit - floorLog2(cxWidthLuma));
01024     if (pu.cu->affineType == AFFINEMODEL_6PARAM)
01025     {
01026       dMvVerXLuma = (mvLB - mvLT).getHor() << (iBit - floorLog2(cxHeightLuma));
01027       dMvVerYLuma = (mvLB - mvLT).getVer() << (iBit - floorLog2(cxHeightLuma));
01028     }
01029     else
01030     {
01031       dMvVerXLuma = -dMvHorYLuma;
01032       dMvVerYLuma = dMvHorXLuma;
01033     }
01034 
01035     const bool subblkMVSpreadOverLimitLuma = isSubblockVectorSpreadOverLimit(dMvHorXLuma, dMvHorYLuma, dMvVerXLuma, dMvVerYLuma, pu.interDir);
01036 
01037     // get luma MV block by block
01038     for (int h = 0; h < cxHeightLuma; h += lumaBlockHeight)
01039     {
01040       for (int w = 0; w < cxWidthLuma; w += lumaBlockWidth)
01041       {
01042         int mvScaleTmpHor, mvScaleTmpVer;
01043         if (!subblkMVSpreadOverLimitLuma)
01044         {
01045           mvScaleTmpHor = iMvScaleHor + dMvHorXLuma * (halfBWLuma + w) + dMvVerXLuma * (halfBHLuma + h);
01046           mvScaleTmpVer = iMvScaleVer + dMvHorYLuma * (halfBWLuma + w) + dMvVerYLuma * (halfBHLuma + h);
01047         }
01048         else
01049         {
01050           mvScaleTmpHor = iMvScaleHor + dMvHorXLuma * (cxWidthLuma >> 1) + dMvVerXLuma * (cxHeightLuma >> 1);
01051           mvScaleTmpVer = iMvScaleVer + dMvHorYLuma * (cxWidthLuma >> 1) + dMvVerYLuma * (cxHeightLuma >> 1);
01052         }
01053 
01054         roundAffineMv(mvScaleTmpHor, mvScaleTmpVer, shift);
01055         Mv tmpMv(mvScaleTmpHor, mvScaleTmpVer);
01056         tmpMv.clipToStorageBitDepth();
01057         mvScaleTmpHor = tmpMv.getHor();
01058         mvScaleTmpVer = tmpMv.getVer();
01059 
01060         m_storedMv[h / AFFINE_MIN_BLOCK_SIZE * MVBUFFER_SIZE + w / AFFINE_MIN_BLOCK_SIZE].set(mvScaleTmpHor, mvScaleTmpVer);
01061       }
01062     }
01063   }
01064   // get prediction block by block
01065   for ( int h = 0; h < cxHeight; h += blockHeight )
01066   {
01067     for ( int w = 0; w < cxWidth; w += blockWidth )
01068     {
01069 
01070       int iMvScaleTmpHor, iMvScaleTmpVer;
01071       if (compID == COMPONENT_Y || pu.chromaFormat == CHROMA_444)
01072       {
01073         if ( !subblkMVSpreadOverLimit )
01074         {
01075           iMvScaleTmpHor = iMvScaleHor + iDMvHorX * (iHalfBW + w) + iDMvVerX * (iHalfBH + h);
01076           iMvScaleTmpVer = iMvScaleVer + iDMvHorY * (iHalfBW + w) + iDMvVerY * (iHalfBH + h);
01077         }
01078         else
01079         {
01080           iMvScaleTmpHor = iMvScaleHor + iDMvHorX * ( cxWidth >> 1 ) + iDMvVerX * ( cxHeight >> 1 );
01081           iMvScaleTmpVer = iMvScaleVer + iDMvHorY * ( cxWidth >> 1 ) + iDMvVerY * ( cxHeight >> 1 );
01082         }
01083         roundAffineMv(iMvScaleTmpHor, iMvScaleTmpVer, shift);
01084         Mv tmpMv(iMvScaleTmpHor, iMvScaleTmpVer);
01085         tmpMv.clipToStorageBitDepth();
01086         iMvScaleTmpHor = tmpMv.getHor();
01087         iMvScaleTmpVer = tmpMv.getVer();
01088 
01089         // clip and scale
01090         if ( refPic->isWrapAroundEnabled( pu.cs->pps ) )
01091         {
01092           m_storedMv[h / AFFINE_MIN_BLOCK_SIZE * MVBUFFER_SIZE + w / AFFINE_MIN_BLOCK_SIZE].set(iMvScaleTmpHor, iMvScaleTmpVer);
01093           Mv tmpMv(iMvScaleTmpHor, iMvScaleTmpVer);
01094           wrapRef = wrapClipMv( tmpMv, Position( pu.Y().x + w, pu.Y().y + h ), Size( blockWidth, blockHeight ), &sps, pu.cs->pps );
01095           iMvScaleTmpHor = tmpMv.getHor();
01096           iMvScaleTmpVer = tmpMv.getVer();
01097         }
01098         else
01099         {
01100           wrapRef = false;
01101           m_storedMv[h / AFFINE_MIN_BLOCK_SIZE * MVBUFFER_SIZE + w / AFFINE_MIN_BLOCK_SIZE].set(iMvScaleTmpHor, iMvScaleTmpVer);
01102           if (refPic->isRefScaled(pu.cs->pps) == false)
01103           {
01104             clipMv(tmpMv, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps);
01105             iMvScaleTmpHor = tmpMv.getHor();
01106             iMvScaleTmpVer = tmpMv.getVer();
01107           }
01108         }
01109       }
01110       else
01111       {
01112         Mv curMv = m_storedMv[((h << iScaleY) / AFFINE_MIN_BLOCK_SIZE) * MVBUFFER_SIZE + ((w << iScaleX) / AFFINE_MIN_BLOCK_SIZE)] +
01113           m_storedMv[((h << iScaleY) / AFFINE_MIN_BLOCK_SIZE + iScaleY)* MVBUFFER_SIZE + ((w << iScaleX) / AFFINE_MIN_BLOCK_SIZE + iScaleX)];
01114         roundAffineMv(curMv.hor, curMv.ver, 1);
01115         if ( refPic->isWrapAroundEnabled( pu.cs->pps ) )
01116         {
01117           wrapRef = wrapClipMv( curMv, Position( pu.Y().x + ( w << iScaleX ), pu.Y().y + ( h << iScaleY ) ), Size( blockWidth << iScaleX, blockHeight << iScaleY ), &sps, pu.cs->pps );
01118         }
01119         else
01120         {
01121           wrapRef = false;
01122           if (refPic->isRefScaled(pu.cs->pps) == false)
01123           {
01124             clipMv(curMv, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps);
01125           }
01126         }
01127         iMvScaleTmpHor = curMv.hor;
01128         iMvScaleTmpVer = curMv.ver;
01129       }
01130 
01131       if( xPredInterBlkRPR( scalingRatio, *pu.cs->pps, CompArea( compID, chFmt, pu.blocks[compID].offset( w, h ), Size( blockWidth, blockHeight ) ), refPic, Mv( iMvScaleTmpHor, iMvScaleTmpVer ), dstBuf.buf + w + h * dstBuf.stride, dstBuf.stride, bi, wrapRef, clpRng, 2 ) )
01132       {
01133         CHECK( enablePROF, "PROF should be disabled with RPR" );
01134       }
01135       else
01136       {
01137         // get the MV in high precision
01138         int xFrac, yFrac, xInt, yInt;
01139 
01140         if (!iScaleX)
01141         {
01142           xInt  = iMvScaleTmpHor >> 4;
01143           xFrac = iMvScaleTmpHor & 15;
01144         }
01145         else
01146         {
01147           xInt  = iMvScaleTmpHor >> 5;
01148           xFrac = iMvScaleTmpHor & 31;
01149         }
01150         if (!iScaleY)
01151         {
01152           yInt  = iMvScaleTmpVer >> 4;
01153           yFrac = iMvScaleTmpVer & 15;
01154         }
01155         else
01156         {
01157           yInt  = iMvScaleTmpVer >> 5;
01158           yFrac = iMvScaleTmpVer & 31;
01159         }
01160 
01161         const CPelBuf refBuf = refPic->getRecoBuf(
01162           CompArea(compID, chFmt, pu.blocks[compID].offset(xInt + w, yInt + h), pu.blocks[compID]), wrapRef);
01163 
01164         Pel *ref = (Pel *) refBuf.buf;
01165         Pel *dst = dstBuf.buf + w + h * dstBuf.stride;
01166 
01167         int refStride = refBuf.stride;
01168         int dstStride = dstBuf.stride;
01169 
01170         int bw = blockWidth;
01171         int bh = blockHeight;
01172 
01173         if (enablePROF)
01174         {
01175           dst       = dstExtBuf.bufAt(PROF_BORDER_EXT_W, PROF_BORDER_EXT_H);
01176           dstStride = dstExtBuf.stride;
01177         }
01178 
01179         if (yFrac == 0)
01180         {
01181           m_if.filterHor(compID, (Pel *) ref, refStride, dst, dstStride, bw, bh, xFrac, isLast, chFmt, clpRng);
01182         }
01183         else if (xFrac == 0)
01184         {
01185           m_if.filterVer(compID, (Pel *) ref, refStride, dst, dstStride, bw, bh, yFrac, true, isLast, chFmt, clpRng);
01186         }
01187         else
01188         {
01189           m_if.filterHor(compID, (Pel *) ref - ((vFilterSize >> 1) - 1) * refStride, refStride, tmpBuf.buf,
01190                          tmpBuf.stride, bw, bh + vFilterSize - 1, xFrac, false, chFmt, clpRng);
01191           JVET_J0090_SET_CACHE_ENABLE(false);
01192           m_if.filterVer(compID, tmpBuf.buf + ((vFilterSize >> 1) - 1) * tmpBuf.stride, tmpBuf.stride, dst, dstStride,
01193                          bw, bh, yFrac, false, isLast, chFmt, clpRng);
01194           JVET_J0090_SET_CACHE_ENABLE(true);
01195         }
01196         if (enablePROF)
01197         {
01198           const int shift = IF_INTERNAL_FRAC_BITS(clpRng.bd);
01199           const int xOffset = xFrac >> 3;
01200           const int yOffset = yFrac >> 3;
01201 
01202           const int refOffset = (blockHeight + 1) * refStride;
01203           const int dstOffset = (blockHeight + 1) * dstStride;
01204 
01205           const Pel *refPel = ref - (1 - yOffset) * refStride + xOffset - 1;
01206           Pel *      dstPel = dst - dstStride - 1;
01207           for (int pw = 0; pw < blockWidth + 2; pw++)
01208           {
01209             dstPel[pw]             = leftShift_round(refPel[pw], shift) - (Pel) IF_INTERNAL_OFFS;
01210             dstPel[pw + dstOffset] = leftShift_round(refPel[pw + refOffset], shift) - (Pel) IF_INTERNAL_OFFS;
01211           }
01212 
01213           refPel = ref + yOffset * refBuf.stride + xOffset;
01214           dstPel = dst;
01215           for (int ph = 0; ph < blockHeight; ph++, refPel += refStride, dstPel += dstStride)
01216           {
01217             dstPel[-1]         = leftShift_round(refPel[-1], shift) - (Pel) IF_INTERNAL_OFFS;
01218             dstPel[blockWidth] = leftShift_round(refPel[blockWidth], shift) - (Pel) IF_INTERNAL_OFFS;
01219           }
01220 
01221           PelBuf gradXBuf = gradXExt.subBuf(0, 0, blockWidth + 2, blockHeight + 2);
01222           PelBuf gradYBuf = gradYExt.subBuf(0, 0, blockWidth + 2, blockHeight + 2);
01223           g_pelBufOP.profGradFilter(dstExtBuf.buf, dstExtBuf.stride, blockWidth + 2, blockHeight + 2, gradXBuf.stride,
01224                                     gradXBuf.buf, gradYBuf.buf, clpRng.bd);
01225 
01226           const Pel offset = (1 << (shift - 1)) + IF_INTERNAL_OFFS;
01227           Pel *src = dstExtBuf.bufAt(PROF_BORDER_EXT_W, PROF_BORDER_EXT_H);
01228           Pel *gX  = gradXBuf.bufAt(PROF_BORDER_EXT_W, PROF_BORDER_EXT_H);
01229           Pel *gY  = gradYBuf.bufAt(PROF_BORDER_EXT_W, PROF_BORDER_EXT_H);
01230 
01231           Pel *dstY = dstBuf.bufAt(w, h);
01232 
01233           g_pelBufOP.applyPROF(dstY, dstBuf.stride, src, dstExtBuf.stride, blockWidth, blockHeight, gX, gY,
01234                                gradXBuf.stride, dMvScaleHor, dMvScaleVer, blockWidth, bi, shift, offset, clpRng);
01235         }
01236       }
01237     }
01238   }
01239 }
01240 
01241 void InterPrediction::applyBiOptFlow(const PredictionUnit &pu, const CPelUnitBuf &yuvSrc0, const CPelUnitBuf &yuvSrc1, const int &refIdx0, const int &refIdx1, PelUnitBuf &yuvDst, const BitDepths &clipBitDepths)
01242 {
01243   const int     height = yuvDst.Y().height;
01244   const int     width = yuvDst.Y().width;
01245   int           heightG = height + 2 * BIO_EXTEND_SIZE;
01246   int           widthG = width + 2 * BIO_EXTEND_SIZE;
01247   int           offsetPos = widthG*BIO_EXTEND_SIZE + BIO_EXTEND_SIZE;
01248 
01249   Pel*          gradX0 = m_gradX0;
01250   Pel*          gradX1 = m_gradX1;
01251   Pel*          gradY0 = m_gradY0;
01252   Pel*          gradY1 = m_gradY1;
01253 
01254   int           stridePredMC = widthG + 2;
01255   const Pel*    srcY0 = m_filteredBlockTmp[2][COMPONENT_Y] + stridePredMC + 1;
01256   const Pel*    srcY1 = m_filteredBlockTmp[3][COMPONENT_Y] + stridePredMC + 1;
01257   const int     src0Stride = stridePredMC;
01258   const int     src1Stride = stridePredMC;
01259 
01260   Pel*          dstY = yuvDst.Y().buf;
01261   const int     dstStride = yuvDst.Y().stride;
01262   const Pel*    srcY0Temp = srcY0;
01263   const Pel*    srcY1Temp = srcY1;
01264 
01265   for (int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++)
01266   {
01267     Pel* dstTempPtr = m_filteredBlockTmp[2 + refList][COMPONENT_Y] + stridePredMC + 1;
01268     Pel* gradY = (refList == 0) ? m_gradY0 : m_gradY1;
01269     Pel* gradX = (refList == 0) ? m_gradX0 : m_gradX1;
01270 
01271     xBioGradFilter(dstTempPtr, stridePredMC, widthG, heightG, widthG, gradX, gradY, clipBitDepths.recon[toChannelType(COMPONENT_Y)]);
01272     Pel* padStr = m_filteredBlockTmp[2 + refList][COMPONENT_Y] + 2 * stridePredMC + 2;
01273     for (int y = 0; y< height; y++)
01274     {
01275       padStr[-1] = padStr[0];
01276       padStr[width] = padStr[width - 1];
01277       padStr += stridePredMC;
01278     }
01279 
01280     padStr = m_filteredBlockTmp[2 + refList][COMPONENT_Y] + 2 * stridePredMC + 1;
01281     ::memcpy(padStr - stridePredMC, padStr, sizeof(Pel)*(widthG));
01282     ::memcpy(padStr + height*stridePredMC, padStr + (height - 1)*stridePredMC, sizeof(Pel)*(widthG));
01283   }
01284 
01285   const ClpRng& clpRng = pu.cu->cs->slice->clpRng(COMPONENT_Y);
01286   const int   bitDepth = clipBitDepths.recon[toChannelType(COMPONENT_Y)];
01287   const int   shiftNum = IF_INTERNAL_FRAC_BITS(bitDepth) + 1;
01288   const int   offset = (1 << (shiftNum - 1)) + 2 * IF_INTERNAL_OFFS;
01289   const int   limit = ( 1 << 4 ) - 1;
01290 
01291   int xUnit = (width >> 2);
01292   int yUnit = (height >> 2);
01293 
01294   Pel *dstY0 = dstY;
01295   gradX0 = m_gradX0; gradX1 = m_gradX1;
01296   gradY0 = m_gradY0; gradY1 = m_gradY1;
01297 
01298   for (int yu = 0; yu < yUnit; yu++)
01299   {
01300     for (int xu = 0; xu < xUnit; xu++)
01301     {
01302       int tmpx = 0, tmpy = 0;
01303       int sumAbsGX = 0, sumAbsGY = 0, sumDIX = 0, sumDIY = 0;
01304       int sumSignGY_GX = 0;
01305 
01306       Pel* pGradX0Tmp = m_gradX0 + (xu << 2) + (yu << 2) * widthG;
01307       Pel* pGradX1Tmp = m_gradX1 + (xu << 2) + (yu << 2) * widthG;
01308       Pel* pGradY0Tmp = m_gradY0 + (xu << 2) + (yu << 2) * widthG;
01309       Pel* pGradY1Tmp = m_gradY1 + (xu << 2) + (yu << 2) * widthG;
01310       const Pel* SrcY1Tmp = srcY1 + (xu << 2) + (yu << 2) * src1Stride;
01311       const Pel* SrcY0Tmp = srcY0 + (xu << 2) + (yu << 2) * src0Stride;
01312 
01313       g_pelBufOP.calcBIOSums(SrcY0Tmp, SrcY1Tmp, pGradX0Tmp, pGradX1Tmp, pGradY0Tmp, pGradY1Tmp, xu, yu, src0Stride, src1Stride, widthG, bitDepth, &sumAbsGX, &sumAbsGY, &sumDIX, &sumDIY, &sumSignGY_GX);
01314       tmpx = (sumAbsGX == 0 ? 0 : rightShiftMSB(sumDIX << 2, sumAbsGX));
01315       tmpx = Clip3(-limit, limit, tmpx);
01316 
01317       int     mainsGxGy = sumSignGY_GX >> 12;
01318       int     secsGxGy = sumSignGY_GX & ((1 << 12) - 1);
01319       int     tmpData = tmpx * mainsGxGy;
01320       tmpData = ((tmpData << 12) + tmpx*secsGxGy) >> 1;
01321       tmpy = (sumAbsGY == 0 ? 0 : rightShiftMSB(((sumDIY << 2) - tmpData), sumAbsGY));
01322       tmpy = Clip3(-limit, limit, tmpy);
01323       srcY0Temp = srcY0 + (stridePredMC + 1) + ((yu*src0Stride + xu) << 2);
01324       srcY1Temp = srcY1 + (stridePredMC + 1) + ((yu*src0Stride + xu) << 2);
01325       gradX0 = m_gradX0 + offsetPos + ((yu*widthG + xu) << 2);
01326       gradX1 = m_gradX1 + offsetPos + ((yu*widthG + xu) << 2);
01327       gradY0 = m_gradY0 + offsetPos + ((yu*widthG + xu) << 2);
01328       gradY1 = m_gradY1 + offsetPos + ((yu*widthG + xu) << 2);
01329 
01330       dstY0 = dstY + ((yu*dstStride + xu) << 2);
01331       xAddBIOAvg4(srcY0Temp, src0Stride, srcY1Temp, src1Stride, dstY0, dstStride, gradX0, gradX1, gradY0, gradY1, widthG, (1 << 2), (1 << 2), (int)tmpx, (int)tmpy, shiftNum, offset, clpRng);
01332     }  // xu
01333   }  // yu
01334 }
01335 
