01358 void InterPrediction::xWeightedAverage(const PredictionUnit& pu, const CPelUnitBuf& pcYuvSrc0, const CPelUnitBuf& pcYuvSrc1, PelUnitBuf& pcYuvDst, const BitDepths& clipBitDepths, const ClpRngs& clpRngs, const bool& bioApplied, bool lumaOnly, bool chromaOnly, PelUnitBuf* yuvDstTmp /*= NULL*/)
01359 {
01360   CHECK( (chromaOnly && lumaOnly), "should not happen" );
01361 
01362   const int iRefIdx0 = pu.refIdx[0];
01363   const int iRefIdx1 = pu.refIdx[1];
01364 
01365   if( iRefIdx0 >= 0 && iRefIdx1 >= 0 )
01366   {
01367     if( pu.cu->BcwIdx != BCW_DEFAULT && (yuvDstTmp || !pu.ciipFlag) )
01368     {
01369       CHECK(bioApplied, "Bcw is disallowed with BIO");
01370       pcYuvDst.addWeightedAvg(pcYuvSrc0, pcYuvSrc1, clpRngs, pu.cu->BcwIdx, chromaOnly, lumaOnly);
01371       if (yuvDstTmp)
01372         yuvDstTmp->addAvg(pcYuvSrc0, pcYuvSrc1, clpRngs, chromaOnly, lumaOnly);
01373       return;
01374     }
01375     if (bioApplied)
01376     {
01377       const int  src0Stride = pu.lwidth() + 2 * BIO_EXTEND_SIZE + 2;
01378       const int  src1Stride = pu.lwidth() + 2 * BIO_EXTEND_SIZE + 2;
01379       const Pel* pSrcY0 = m_filteredBlockTmp[2][COMPONENT_Y] + 2 * src0Stride + 2;
01380       const Pel* pSrcY1 = m_filteredBlockTmp[3][COMPONENT_Y] + 2 * src1Stride + 2;
01381 
01382       bool bioEnabled = true;
01383       if (bioEnabled)
01384       {
01385         applyBiOptFlow(pu, pcYuvSrc0, pcYuvSrc1, iRefIdx0, iRefIdx1, pcYuvDst, clipBitDepths);
01386         if (yuvDstTmp)
01387           yuvDstTmp->bufs[0].addAvg(CPelBuf(pSrcY0, src0Stride, pu.lumaSize()), CPelBuf(pSrcY1, src1Stride, pu.lumaSize()), clpRngs.comp[0]);
01388       }
01389       else
01390       {
01391         pcYuvDst.bufs[0].addAvg(CPelBuf(pSrcY0, src0Stride, pu.lumaSize()), CPelBuf(pSrcY1, src1Stride, pu.lumaSize()), clpRngs.comp[0]);
01392         if (yuvDstTmp)
01393           yuvDstTmp->bufs[0].copyFrom(pcYuvDst.bufs[0]);
01394       }
01395     }
01396     if (!bioApplied && (lumaOnly || chromaOnly))
01397     {
01398       pcYuvDst.addAvg(pcYuvSrc0, pcYuvSrc1, clpRngs, chromaOnly, lumaOnly);
01399     }
01400     else
01401     {
01402       pcYuvDst.addAvg(pcYuvSrc0, pcYuvSrc1, clpRngs, bioApplied);
01403     }
01404     if (yuvDstTmp)
01405     {
01406       if (bioApplied)
01407       {
01408         if (isChromaEnabled(yuvDstTmp->chromaFormat))
01409         {
01410           yuvDstTmp->bufs[1].copyFrom(pcYuvDst.bufs[1]);
01411           yuvDstTmp->bufs[2].copyFrom(pcYuvDst.bufs[2]);
01412         }
01413       }
01414       else
01415       {
01416         yuvDstTmp->copyFrom(pcYuvDst, lumaOnly, chromaOnly);
01417       }
01418     }
01419   }
01420   else if( iRefIdx0 >= 0 && iRefIdx1 < 0 )
01421   {
01422     if( pu.cu->geoFlag )
01423     {
01424       pcYuvDst.copyFrom( pcYuvSrc0 );
01425     }
01426     else
01427     {
01428       pcYuvDst.copyClip( pcYuvSrc0, clpRngs, lumaOnly, chromaOnly );
01429     }
01430     if (yuvDstTmp)
01431     {
01432       yuvDstTmp->copyFrom( pcYuvDst, lumaOnly, chromaOnly );
01433     }
01434   }
01435   else if( iRefIdx0 < 0 && iRefIdx1 >= 0 )
01436   {
01437     if( pu.cu->geoFlag )
01438     {
01439       pcYuvDst.copyFrom( pcYuvSrc1 );
01440     }
01441     else
01442     {
01443       pcYuvDst.copyClip( pcYuvSrc1, clpRngs, lumaOnly, chromaOnly );
01444     }
01445     if (yuvDstTmp)
01446     {
01447       yuvDstTmp->copyFrom(pcYuvDst, lumaOnly, chromaOnly);
01448     }
01449   }
01450 }
