01452 
01453 void InterPrediction::motionCompensation( PredictionUnit &pu, PelUnitBuf &predBuf, const RefPicList &eRefPicList
01454   , const bool luma, const bool chroma
01455   , PelUnitBuf* predBufWOBIO /*= NULL*/
01456 )
01457 {
01458   // Note: there appears to be an interaction with weighted prediction that
01459   // makes the code follow different paths if chroma is on or off (in the encoder).
01460   // Therefore for 4:0:0, "chroma" is not changed to false.
01461   CHECK(predBufWOBIO && pu.ciipFlag, "the case should not happen!");
01462 
01463   if (!pu.cs->pcv->isEncoder)
01464   {
01465     if (CU::isIBC(*pu.cu))
01466     {
01467       CHECK(!luma, "IBC only for Chroma is not allowed.");
01468       xIntraBlockCopy(pu, predBuf, COMPONENT_Y);
01469       if (chroma && isChromaEnabled(pu.chromaFormat))
01470       {
01471         xIntraBlockCopy(pu, predBuf, COMPONENT_Cb);
01472         xIntraBlockCopy(pu, predBuf, COMPONENT_Cr);
01473       }
01474       return;
01475     }
01476   }
01477   // dual tree handling for IBC as the only ref
01478   if ((!luma || !chroma) && eRefPicList == REF_PIC_LIST_0)
01479   {
01480     xPredInterUni(pu, eRefPicList, predBuf, false, false, luma, chroma);
01481     return;
01482   }
01483   // else, go with regular MC below
01484         CodingStructure &cs = *pu.cs;
01485   const PPS &pps            = *cs.pps;
01486   const SliceType sliceType =  cs.slice->getSliceType();
01487 
01488   if( eRefPicList != REF_PIC_LIST_X )
01489   {
01490     CHECK(predBufWOBIO != NULL, "the case should not happen!");
01491     if ((CU::isIBC(*pu.cu) == false) && ((sliceType == P_SLICE && pps.getUseWP()) || (sliceType == B_SLICE && pps.getWPBiPred())))
01492     {
01493       xPredInterUni(pu, eRefPicList, predBuf, true, false, luma, chroma);
01494       xWeightedPredictionUni(pu, predBuf, eRefPicList, predBuf, -1, m_maxCompIDToPred, (luma && !chroma),
01495                              (!luma && chroma));
01496     }
01497     else
01498     {
01499       xPredInterUni(pu, eRefPicList, predBuf, false, false, luma, chroma);
01500     }
01501   }
01502   else
01503   {
01504     CHECK( !pu.cu->affine && pu.refIdx[0] >= 0 && pu.refIdx[1] >= 0 && ( pu.lwidth() + pu.lheight() == 12 ), "invalid 4x8/8x4 bi-predicted blocks" );
01505     int refIdx0 = pu.refIdx[REF_PIC_LIST_0];
01506     int refIdx1 = pu.refIdx[REF_PIC_LIST_1];
01507 
01508     const WPScalingParam *wp0 = pu.cs->slice->getWpScaling(REF_PIC_LIST_0, refIdx0);
01509     const WPScalingParam *wp1 = pu.cs->slice->getWpScaling(REF_PIC_LIST_1, refIdx1);
01510 
01511     bool bioApplied = false;
01512     const Slice &slice = *pu.cs->slice;
01513     if (pu.cs->sps->getBDOFEnabledFlag() && (!pu.cs->picHeader->getBdofDisabledFlag()))
01514     {
01515       if (pu.cu->affine || m_subPuMC)
01516       {
01517         bioApplied = false;
01518       }
01519       else
01520       {
01521         const bool biocheck0 =
01522           !((WPScalingParam::isWeighted(wp0) || WPScalingParam::isWeighted(wp1)) && slice.getSliceType() == B_SLICE);
01523         const bool biocheck1 = !(pps.getUseWP() && slice.getSliceType() == P_SLICE);
01524         if (biocheck0
01525           && biocheck1
01526           && PU::isBiPredFromDifferentDirEqDistPoc(pu)
01527           && (pu.Y().height >= 8)
01528           && (pu.Y().width >= 8)
01529           && ((pu.Y().height * pu.Y().width) >= 128)
01530           )
01531         {
01532           bioApplied = true;
01533         }
01534       }
01535 
01536       if (bioApplied && pu.ciipFlag)
01537       {
01538         bioApplied = false;
01539       }
01540 
01541       if (bioApplied && pu.cu->smvdMode)
01542       {
01543         bioApplied = false;
01544       }
01545       if (pu.cu->cs->sps->getUseBcw() && bioApplied && pu.cu->BcwIdx != BCW_DEFAULT)
01546       {
01547         bioApplied = false;
01548       }
01549       if (pu.mmvdEncOptMode == 2 && pu.mmvdMergeFlag)
01550       {
01551         bioApplied = false;
01552       }
01553     }
01554 
01555     bool refIsScaled = ( refIdx0 < 0 ? false : pu.cu->slice->getRefPic( REF_PIC_LIST_0, refIdx0 )->isRefScaled( pu.cs->pps ) ) ||
01556                        ( refIdx1 < 0 ? false : pu.cu->slice->getRefPic( REF_PIC_LIST_1, refIdx1 )->isRefScaled( pu.cs->pps ) );
01557     bioApplied = refIsScaled ? false : bioApplied;
01558     bool dmvrApplied = false;
01559     dmvrApplied = (pu.mvRefine) && PU::checkDMVRCondition(pu);
01560     if ((pu.lumaSize().width > MAX_BDOF_APPLICATION_REGION || pu.lumaSize().height > MAX_BDOF_APPLICATION_REGION) && pu.mergeType != MRG_TYPE_SUBPU_ATMVP && (bioApplied && !dmvrApplied))
01561     {
01562       xSubPuBio(pu, predBuf, eRefPicList, predBufWOBIO);
01563     }
01564     else
01565     {
01566       if (pu.mergeType != MRG_TYPE_DEFAULT_N && pu.mergeType != MRG_TYPE_IBC)
01567       {
01568         CHECK(predBufWOBIO != NULL, "the case should not happen!");
01569         xSubPuMC(pu, predBuf, eRefPicList, luma, chroma);
01570       }
01571       else if (xCheckIdenticalMotion(pu))
01572       {
01573         xPredInterUni(pu, REF_PIC_LIST_0, predBuf, false, false, luma, chroma);
01574         if (predBufWOBIO)
01575           predBufWOBIO->copyFrom(predBuf, (luma && !chroma), (chroma && !luma));
01576       }
01577       else
01578       {
01579         xPredInterBi(pu, predBuf, luma, chroma, predBufWOBIO);
01580       }
01581     }
01582   }
01583   return;
01584 }
