01612 void InterPrediction::motionCompensationGeo( CodingUnit &cu, MergeCtx &geoMrgCtx )
01613 {
01614   const uint8_t splitDir = cu.firstPU->geoSplitDir;
01615   const uint8_t candIdx0 = cu.firstPU->geoMergeIdx0;
01616   const uint8_t candIdx1 = cu.firstPU->geoMergeIdx1;
01617   for( auto &pu : CU::traversePUs( cu ) )
01618   {
01619     const UnitArea localUnitArea( cu.cs->area.chromaFormat, Area( 0, 0, pu.lwidth(), pu.lheight() ) );
01620     PelUnitBuf tmpGeoBuf0 = m_geoPartBuf[0].getBuf( localUnitArea );
01621     PelUnitBuf tmpGeoBuf1 = m_geoPartBuf[1].getBuf( localUnitArea );
01622     PelUnitBuf predBuf    = cu.cs->getPredBuf( pu );
01623 
01624     geoMrgCtx.setMergeInfo( pu, candIdx0 );
01625     PU::spanMotionInfo( pu );
01626     motionCompensation(pu, tmpGeoBuf0, REF_PIC_LIST_X, true, isChromaEnabled(pu.chromaFormat)); // TODO: check 4:0:0 interaction with weighted prediction.
01627     if( g_mctsDecCheckEnabled && !MCTSHelper::checkMvBufferForMCTSConstraint( pu, true ) )
01628     {
01629       printf( "DECODER_GEO_PU: pu motion vector across tile boundaries (%d,%d,%d,%d)\n", pu.lx(), pu.ly(), pu.lwidth(), pu.lheight() );
01630     }
01631 
01632     geoMrgCtx.setMergeInfo( pu, candIdx1 );
01633     PU::spanMotionInfo( pu );
01634     motionCompensation(pu, tmpGeoBuf1, REF_PIC_LIST_X, true, isChromaEnabled(pu.chromaFormat)); // TODO: check 4:0:0 interaction with weighted prediction.
01635     if( g_mctsDecCheckEnabled && !MCTSHelper::checkMvBufferForMCTSConstraint( pu, true ) )
01636     {
01637       printf( "DECODER_GEO_PU: pu motion vector across tile boundaries (%d,%d,%d,%d)\n", pu.lx(), pu.ly(), pu.lwidth(), pu.lheight() );
01638     }
01639     weightedGeoBlk(pu, splitDir, isChromaEnabled(pu.chromaFormat)? MAX_NUM_CHANNEL_TYPE : CHANNEL_TYPE_LUMA, predBuf, tmpGeoBuf0, tmpGeoBuf1);
01640   }
01641 }
