01667 void InterPrediction::xPrefetch(PredictionUnit& pu, PelUnitBuf &pcPad, RefPicList refId, bool forLuma)
01668 {
01669   int offset, width, height;
01670   Mv cMv;
01671   const Picture* refPic = pu.cu->slice->getRefPic( refId, pu.refIdx[refId] )->unscaledPic;
01672   int mvShift = (MV_FRACTIONAL_BITS_INTERNAL);
01673 
01674   int start = 0;
01675   int end = MAX_NUM_COMPONENT;
01676 
01677   start = forLuma ? 0 : 1;
01678   end = forLuma ? 1 : MAX_NUM_COMPONENT;
01679 
01680   for (int compID = start; compID < end; compID++)
01681   {
01682     cMv = Mv(pu.mv[refId].getHor(), pu.mv[refId].getVer());
01683     pcPad.bufs[compID].stride = (pcPad.bufs[compID].width + (2 * DMVR_NUM_ITERATION) + NTAPS_LUMA);
01684     int filtersize = (compID == (COMPONENT_Y)) ? NTAPS_LUMA : NTAPS_CHROMA;
01685     width = pcPad.bufs[compID].width;
01686     height = pcPad.bufs[compID].height;
01687     offset = (DMVR_NUM_ITERATION) * (pcPad.bufs[compID].stride + 1);
01688     int mvshiftTempHor = mvShift + getComponentScaleX((ComponentID)compID, pu.chromaFormat);
01689     int mvshiftTempVer = mvShift + getComponentScaleY((ComponentID)compID, pu.chromaFormat);
01690     width += (filtersize - 1);
01691     height += (filtersize - 1);
01692     cMv += Mv(-(((filtersize >> 1) - 1) << mvshiftTempHor),
01693       -(((filtersize >> 1) - 1) << mvshiftTempVer));
01694     bool wrapRef = false;
01695     if( refPic->isWrapAroundEnabled( pu.cs->pps ) )
01696     {
01697       wrapRef = wrapClipMv( cMv, pu.blocks[0].pos(), pu.blocks[0].size(), pu.cs->sps, pu.cs->pps );
01698     }
01699     else
01700     {
01701       clipMv( cMv, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps );
01702     }
01703     /* Pre-fetch similar to HEVC*/
01704     {
01705       CPelBuf refBuf;
01706       Position Rec_offset = pu.blocks[compID].pos().offset(cMv.getHor() >> mvshiftTempHor, cMv.getVer() >> mvshiftTempVer);
01707       refBuf = refPic->getRecoBuf(CompArea((ComponentID)compID, pu.chromaFormat, Rec_offset, pu.blocks[compID].size()), wrapRef);
01708       PelBuf &dstBuf = pcPad.bufs[compID];
01709       g_pelBufOP.copyBuffer((Pel *)refBuf.buf, refBuf.stride, ((Pel *)dstBuf.buf) + offset, dstBuf.stride, width, height);
01710     }
01711   }
01712 }
01713 void InterPrediction::xPad(PredictionUnit& pu, PelUnitBuf &pcPad, RefPicList refId)
01714 {
01715   int offset = 0, width, height;
01716   int padsize;
01717   Mv cMv;
01718   for (int compID = 0; compID < getNumberValidComponents(pu.chromaFormat); compID++)
01719   {
01720     int filtersize = (compID == (COMPONENT_Y)) ? NTAPS_LUMA : NTAPS_CHROMA;
01721     width = pcPad.bufs[compID].width;
01722     height = pcPad.bufs[compID].height;
01723     offset = (DMVR_NUM_ITERATION) * (pcPad.bufs[compID].stride + 1);
01724     /*using the larger padsize for 422*/
01725     padsize = (DMVR_NUM_ITERATION) >> getComponentScaleY((ComponentID)compID, pu.chromaFormat);
01726     width += (filtersize - 1);
01727     height += (filtersize - 1);
01728     /*padding on all side of size DMVR_PAD_LENGTH*/
01729     g_pelBufOP.padding(pcPad.bufs[compID].buf + offset, pcPad.bufs[compID].stride, width, height, padsize);
01730   }
01731 }
01732 inline int32_t div_for_maxq7(int64_t N, int64_t D)
01733 {
01734   int32_t sign, q;
01735   sign = 0;
01736   if (N < 0)
01737   {
01738     sign = 1;
01739     N = -N;
01740   }
01741 
01742   q = 0;
01743   D = (D << 3);
01744   if (N >= D)
01745   {
01746     N -= D;
01747     q++;
01748   }
01749   q = (q << 1);
01750 
01751   D = (D >> 1);
01752   if (N >= D)
01753   {
01754     N -= D;
01755     q++;
01756   }
01757   q = (q << 1);
01758 
01759   if (N >= (D >> 1))
01760   {
01761     q++;
01762   }
01763   if (sign)
01764   {
01765     return (-q);
01766   }
01767   return(q);
01768 }
01769 
01770 void xSubPelErrorSrfc(uint64_t *sadBuffer, int32_t *deltaMv)
01771 {
01772   int64_t numerator, denominator;
01773   int32_t mvDeltaSubPel;
01774   int32_t mvSubPelLvl = 4;/*1: half pel, 2: Qpel, 3:1/8, 4: 1/16*/
01775                                                         /*horizontal*/
01776   numerator   = (int64_t)((sadBuffer[1] - sadBuffer[3]) << mvSubPelLvl);
01777   denominator = (int64_t)((sadBuffer[1] + sadBuffer[3] - (sadBuffer[0] << 1)));
01778 
01779   if (0 != denominator)
01780   {
01781     if ((sadBuffer[1] != sadBuffer[0]) && (sadBuffer[3] != sadBuffer[0]))
01782     {
01783       mvDeltaSubPel = div_for_maxq7(numerator, denominator);
01784       deltaMv[0]    = (mvDeltaSubPel);
01785     }
01786     else
01787     {
01788       if (sadBuffer[1] == sadBuffer[0])
01789       {
01790         deltaMv[0] = -8;   // half pel
01791       }
01792       else
01793       {
01794         deltaMv[0] = 8;   // half pel
01795       }
01796     }
01797   }
01798 
01799   /*vertical*/
01800   numerator   = (int64_t)((sadBuffer[2] - sadBuffer[4]) << mvSubPelLvl);
01801   denominator = (int64_t)((sadBuffer[2] + sadBuffer[4] - (sadBuffer[0] << 1)));
01802   if (0 != denominator)
01803   {
01804     if ((sadBuffer[2] != sadBuffer[0]) && (sadBuffer[4] != sadBuffer[0]))
01805     {
01806       mvDeltaSubPel = div_for_maxq7(numerator, denominator);
01807       deltaMv[1]    = (mvDeltaSubPel);
01808     }
01809     else
01810     {
01811       if (sadBuffer[2] == sadBuffer[0])
01812       {
01813         deltaMv[1] = -8;   // half pel
01814       }
01815       else
01816       {
01817         deltaMv[1] = 8;   // half pel
01818       }
01819     }
01820   }
01821   return;
01822 }
01823 
01824 void InterPrediction::xBIPMVRefine(int bd, Pel *pRefL0, Pel *pRefL1, uint64_t& minCost, int16_t *deltaMV, uint64_t *pSADsArray, int width, int height)
01825 {
01826   const int32_t refStrideL0 = m_biLinearBufStride;
01827   const int32_t refStrideL1 = m_biLinearBufStride;
01828   Pel *pRefL0Orig = pRefL0;
01829   Pel *pRefL1Orig = pRefL1;
01830   for (int nIdx = 0; (nIdx < 25); ++nIdx)
01831   {
01832     int32_t sadOffset = ((m_pSearchOffset[nIdx].getVer() * ((2 * DMVR_NUM_ITERATION) + 1)) + m_pSearchOffset[nIdx].getHor());
01833     pRefL0 = pRefL0Orig + m_pSearchOffset[nIdx].hor + (m_pSearchOffset[nIdx].ver * refStrideL0);
01834     pRefL1 = pRefL1Orig - m_pSearchOffset[nIdx].hor - (m_pSearchOffset[nIdx].ver * refStrideL1);
01835     if (*(pSADsArray + sadOffset) == MAX_UINT64)
01836     {
01837       const uint64_t cost = xDMVRCost(bd, pRefL0, refStrideL0, pRefL1, refStrideL1, width, height);
01838       *(pSADsArray + sadOffset) = cost;
01839     }
01840     if (*(pSADsArray + sadOffset) < minCost)
01841     {
01842       minCost = *(pSADsArray + sadOffset);
01843       deltaMV[0] = m_pSearchOffset[nIdx].getHor();
01844       deltaMV[1] = m_pSearchOffset[nIdx].getVer();
01845     }
01846   }
01847 }
01848 
01849 void InterPrediction::xFinalPaddedMCForDMVR(PredictionUnit &pu, PelUnitBuf &pcYuvSrc0, PelUnitBuf &pcYuvSrc1,
01850                                             PelUnitBuf &pcPad0, PelUnitBuf &pcPad1, const bool bioApplied,
01851                                             const Mv mergeMV[NUM_REF_PIC_LIST_01], bool blockMoved)
01852 {
01853   int offset, deltaIntMvX, deltaIntMvY;
01854 
01855   PelUnitBuf pcYUVTemp = pcYuvSrc0;
01856   PelUnitBuf pcPadTemp = pcPad0;
01857   /*always high precision MVs are used*/
01858   int mvShift = MV_FRACTIONAL_BITS_INTERNAL;
01859 
01860   for (int k = 0; k < NUM_REF_PIC_LIST_01; k++)
01861   {
01862     RefPicList refId = (RefPicList)k;
01863     Mv cMv = pu.mv[refId];
01864     m_iRefListIdx = refId;
01865     const Picture* refPic = pu.cu->slice->getRefPic( refId, pu.refIdx[refId] )->unscaledPic;
01866     Mv cMvClipped = cMv;
01867     if( !pu.cs->pps->getWrapAroundEnabledFlag() )
01868     {
01869       clipMv( cMvClipped, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps );
01870     }
01871 
01872     Mv startMv = mergeMV[refId];
01873 
01874     if( g_mctsDecCheckEnabled && !MCTSHelper::checkMvForMCTSConstraint( pu, startMv, MV_PRECISION_INTERNAL ) )
01875     {
01876       const Area& tileArea = pu.cs->picture->mctsInfo.getTileArea();
01877       printf( "Attempt an access over tile boundary at block %d,%d %d,%d with MV %d,%d (in Tile TL: %d,%d BR: %d,%d)\n",
01878         pu.lx(), pu.ly(), pu.lwidth(), pu.lheight(), startMv.getHor(), startMv.getVer(), tileArea.topLeft().x, tileArea.topLeft().y, tileArea.bottomRight().x, tileArea.bottomRight().y );
01879       THROW( "MCTS constraint failed!" );
01880     }
01881     for (int compID = 0; compID < getNumberValidComponents(pu.chromaFormat); compID++)
01882     {
01883       Pel *srcBufPelPtr = NULL;
01884       int pcPadstride = 0;
01885       if (blockMoved || (compID == 0))
01886       {
01887         pcPadstride = pcPadTemp.bufs[compID].stride;
01888         int mvshiftTempHor = mvShift + getComponentScaleX((ComponentID)compID, pu.chromaFormat);
01889         int mvshiftTempVer = mvShift + getComponentScaleY((ComponentID)compID, pu.chromaFormat);
01890         int leftPixelExtra;
01891         if (compID == COMPONENT_Y)
01892         {
01893           leftPixelExtra = (NTAPS_LUMA >> 1) - 1;
01894         }
01895         else
01896         {
01897           leftPixelExtra = (NTAPS_CHROMA >> 1) - 1;
01898         }
01899         PelBuf &srcBuf = pcPadTemp.bufs[compID];
01900         deltaIntMvX    = (cMv.getHor() >> mvshiftTempHor) - (startMv.getHor() >> mvshiftTempHor);
01901         deltaIntMvY    = (cMv.getVer() >> mvshiftTempVer) - (startMv.getVer() >> mvshiftTempVer);
01902 
01903         CHECK((abs(deltaIntMvX) > DMVR_NUM_ITERATION) || (abs(deltaIntMvY) > DMVR_NUM_ITERATION), "not expected DMVR movement");
01904 
01905         offset = (DMVR_NUM_ITERATION + leftPixelExtra) * (pcPadTemp.bufs[compID].stride + 1);
01906         offset += (deltaIntMvY)* pcPadTemp.bufs[compID].stride;
01907         offset += (deltaIntMvX);
01908         srcBufPelPtr = (srcBuf.buf + offset);
01909       }
01910       JVET_J0090_SET_CACHE_ENABLE(false);
01911       xPredInterBlk((ComponentID) compID, pu, refPic, cMvClipped, pcYUVTemp, true,
01912                     pu.cs->slice->getClpRngs().comp[compID], bioApplied, false,
01913                     pu.cu->slice->getScalingRatio(refId, pu.refIdx[refId]), 0, 0, 0, srcBufPelPtr, pcPadstride);
01914       JVET_J0090_SET_CACHE_ENABLE(false);
01915     }
01916     pcYUVTemp = pcYuvSrc1;
01917     pcPadTemp = pcPad1;
01918   }
01919 }
01920 
01921 uint64_t InterPrediction::xDMVRCost(int bitDepth, Pel* pOrg, uint32_t refStride, const Pel* pRef, uint32_t orgStride, int width, int height)
01922 {
01923   DistParam cDistParam;
01924   cDistParam.applyWeight = false;
01925   cDistParam.useMR = false;
01926   m_pcRdCost->setDistParam(cDistParam, pOrg, pRef, orgStride, refStride, bitDepth, COMPONENT_Y, width, height, 1);
01927   uint64_t uiCost = cDistParam.distFunc(cDistParam);
01928   return uiCost>>1;
01929 }
01930 
01931 void xDMVRSubPixelErrorSurface(bool notZeroCost, int16_t *totalDeltaMV, int16_t *deltaMV, uint64_t *pSADsArray)
01932 {
01933 
01934   int sadStride = (((2 * DMVR_NUM_ITERATION) + 1));
01935   uint64_t sadbuffer[5];
01936   if (notZeroCost && (abs(totalDeltaMV[0]) != (2 << MV_FRACTIONAL_BITS_INTERNAL))
01937     && (abs(totalDeltaMV[1]) != (2 << MV_FRACTIONAL_BITS_INTERNAL)))
01938   {
01939     int32_t tempDeltaMv[2] = { 0,0 };
01940     sadbuffer[0] = pSADsArray[0];
01941     sadbuffer[1] = pSADsArray[-1];
01942     sadbuffer[2] = pSADsArray[-sadStride];
01943     sadbuffer[3] = pSADsArray[1];
01944     sadbuffer[4] = pSADsArray[sadStride];
01945     xSubPelErrorSrfc(sadbuffer, tempDeltaMv);
01946     totalDeltaMV[0] += tempDeltaMv[0];
01947     totalDeltaMV[1] += tempDeltaMv[1];
01948   }
01949 }
