01951 void InterPrediction::xinitMC(PredictionUnit& pu, const ClpRngs &clpRngs)
01952 {
01953   const int refIdx0 = pu.refIdx[0];
01954   const int refIdx1 = pu.refIdx[1];
01955   /*use merge MV as starting MV*/
01956   Mv mergeMVL0(pu.mv[REF_PIC_LIST_0]);
01957   Mv mergeMVL1(pu.mv[REF_PIC_LIST_1]);
01958 
01959   /*Clip the starting MVs*/
01960   if( !pu.cs->pps->getWrapAroundEnabledFlag() )
01961   {
01962     clipMv( mergeMVL0, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps );
01963     clipMv( mergeMVL1, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps );
01964   }
01965 
01966   /*L0 MC for refinement*/
01967   {
01968     int offset;
01969     int leftPixelExtra = (NTAPS_LUMA >> 1) - 1;
01970     offset = (DMVR_NUM_ITERATION + leftPixelExtra) * (m_cYuvRefBuffDMVRL0.bufs[COMPONENT_Y].stride + 1);
01971     offset += (-(int)DMVR_NUM_ITERATION)* (int)m_cYuvRefBuffDMVRL0.bufs[COMPONENT_Y].stride;
01972     offset += (-(int)DMVR_NUM_ITERATION);
01973     PelBuf srcBuf = m_cYuvRefBuffDMVRL0.bufs[COMPONENT_Y];
01974     PelUnitBuf yuvPredTempL0 = PelUnitBuf(pu.chromaFormat, PelBuf(m_cYuvPredTempDMVRL0,
01975       m_biLinearBufStride
01976       , pu.lwidth() + (2 * DMVR_NUM_ITERATION), pu.lheight() + (2 * DMVR_NUM_ITERATION)));
01977 
01978     xPredInterBlk( COMPONENT_Y, pu, pu.cu->slice->getRefPic( REF_PIC_LIST_0, refIdx0 )->unscaledPic, mergeMVL0, yuvPredTempL0, true, clpRngs.comp[COMPONENT_Y],
01979       false, false, pu.cu->slice->getScalingRatio( REF_PIC_LIST_0, refIdx0 ), pu.lwidth() + ( 2 * DMVR_NUM_ITERATION ), pu.lheight() + ( 2 * DMVR_NUM_ITERATION ), true, ( (Pel *)srcBuf.buf ) + offset, srcBuf.stride );
01980   }
01981 
01982   /*L1 MC for refinement*/
01983   {
01984     int offset;
01985     int leftPixelExtra = (NTAPS_LUMA >> 1) - 1;
01986     offset = (DMVR_NUM_ITERATION + leftPixelExtra) * (m_cYuvRefBuffDMVRL1.bufs[COMPONENT_Y].stride + 1);
01987     offset += (-(int)DMVR_NUM_ITERATION)* (int)m_cYuvRefBuffDMVRL1.bufs[COMPONENT_Y].stride;
01988     offset += (-(int)DMVR_NUM_ITERATION);
01989     PelBuf srcBuf = m_cYuvRefBuffDMVRL1.bufs[COMPONENT_Y];
01990     PelUnitBuf yuvPredTempL1 = PelUnitBuf(pu.chromaFormat, PelBuf(m_cYuvPredTempDMVRL1,
01991       m_biLinearBufStride
01992       , pu.lwidth() + (2 * DMVR_NUM_ITERATION), pu.lheight() + (2 * DMVR_NUM_ITERATION)));
01993 
01994     xPredInterBlk( COMPONENT_Y, pu, pu.cu->slice->getRefPic( REF_PIC_LIST_1, refIdx1 )->unscaledPic, mergeMVL1, yuvPredTempL1, true, clpRngs.comp[COMPONENT_Y],
01995       false, false, pu.cu->slice->getScalingRatio( REF_PIC_LIST_1, refIdx1 ), pu.lwidth() + ( 2 * DMVR_NUM_ITERATION ), pu.lheight() + ( 2 * DMVR_NUM_ITERATION ), true, ( (Pel *)srcBuf.buf ) + offset, srcBuf.stride );
01996   }
01997 }
01998 
01999 void InterPrediction::xProcessDMVR(PredictionUnit& pu, PelUnitBuf &pcYuvDst, const ClpRngs &clpRngs, const bool bioApplied)
02000 {
02001   int iterationCount = 1;
02002   /*Always High Precision*/
02003   int mvShift = MV_FRACTIONAL_BITS_INTERNAL;
02004 
02005   /*use merge MV as starting MV*/
02006   Mv mergeMv[] = { pu.mv[REF_PIC_LIST_0] , pu.mv[REF_PIC_LIST_1] };
02007 
02008   m_biLinearBufStride = (MAX_CU_SIZE + (2 * DMVR_NUM_ITERATION));
02009 
02010   int dy = std::min<int>(pu.lumaSize().height, DMVR_SUBCU_HEIGHT);
02011   int dx = std::min<int>(pu.lumaSize().width,  DMVR_SUBCU_WIDTH);
02012   Position puPos = pu.lumaPos();
02013 
02014   int bd = pu.cs->slice->getClpRngs().comp[COMPONENT_Y].bd;
02015 
02016   int            bioEnabledThres = 2 * dy * dx;
02017   bool           bioAppliedType[MAX_NUM_SUBCU_DMVR];
02018 
02019 #if JVET_J0090_MEMORY_BANDWITH_MEASURE
02020   JVET_J0090_SET_CACHE_ENABLE(true);
02021   for (int k = 0; k < NUM_REF_PIC_LIST_01; k++)
02022   {
02023     RefPicList refId = (RefPicList)k;
02024     const Picture* refPic = pu.cu->slice->getRefPic(refId, pu.refIdx[refId]);
02025     for (int compID = 0; compID < MAX_NUM_COMPONENT; compID++)
02026     {
02027       Mv cMv = pu.mv[refId];
02028       int mvshiftTemp = mvShift + getComponentScaleX((ComponentID)compID, pu.chromaFormat);
02029       int filtersize = (compID == (COMPONENT_Y)) ? NTAPS_LUMA : NTAPS_CHROMA;
02030       cMv += Mv(-(((filtersize >> 1) - 1) << mvshiftTemp), -(((filtersize >> 1) - 1) << mvshiftTemp));
02031       bool wrapRef = false;
02032       if ( pu.cs->pps->getWrapAroundEnabledFlag() )
02033       {
02034         wrapRef = wrapClipMv(cMv, pu.blocks[0].pos(), pu.blocks[0].size(), pu.cs->sps, pu.cs->pps);
02035       }
02036       else
02037       {
02038         clipMv(cMv, pu.lumaPos(), pu.lumaSize(), *pu.cs->sps, *pu.cs->pps);
02039       }
02040 
02041       int width = pcYuvDst.bufs[compID].width + (filtersize - 1);
02042       int height = pcYuvDst.bufs[compID].height + (filtersize - 1);
02043 
02044       CPelBuf refBuf;
02045       Position recOffset = pu.blocks[compID].pos().offset(cMv.getHor() >> mvshiftTemp, cMv.getVer() >> mvshiftTemp);
02046       refBuf = refPic->getRecoBuf(CompArea((ComponentID)compID, pu.chromaFormat, recOffset, pu.blocks[compID].size()), wrapRef);
02047 
02048       JVET_J0090_SET_REF_PICTURE(refPic, (ComponentID)compID);
02049       for (int row = 0; row < height; row++)
02050       {
02051         for (int col = 0; col < width; col++)
02052         {
02053           JVET_J0090_CACHE_ACCESS(((Pel *)refBuf.buf) + row * refBuf.stride + col, __FILE__, __LINE__);
02054         }
02055       }
02056     }
02057   }
02058   JVET_J0090_SET_CACHE_ENABLE(false);
02059 #endif
02060 
02061   {
02062     int num = 0;
02063 
02064     int scaleX = getComponentScaleX(COMPONENT_Cb, pu.chromaFormat);
02065     int scaleY = getComponentScaleY(COMPONENT_Cb, pu.chromaFormat);
02066     m_biLinearBufStride = (dx + (2 * DMVR_NUM_ITERATION));
02067     // point mc buffer to cetre point to avoid multiplication to reach each iteration to the begining
02068     Pel *biLinearPredL0 = m_cYuvPredTempDMVRL0 + (DMVR_NUM_ITERATION * m_biLinearBufStride) + DMVR_NUM_ITERATION;
02069     Pel *biLinearPredL1 = m_cYuvPredTempDMVRL1 + (DMVR_NUM_ITERATION * m_biLinearBufStride) + DMVR_NUM_ITERATION;
02070 
02071     PredictionUnit subPu = pu;
02072     subPu.UnitArea::operator=(UnitArea(pu.chromaFormat, Area(puPos.x, puPos.y, dx, dy)));
02073     m_cYuvRefBuffDMVRL0 = (pu.chromaFormat == CHROMA_400 ?
02074       PelUnitBuf(pu.chromaFormat, PelBuf(m_cRefSamplesDMVRL0[0], pcYuvDst.Y())) :
02075       PelUnitBuf(pu.chromaFormat, PelBuf(m_cRefSamplesDMVRL0[0], pcYuvDst.Y()),
02076         PelBuf(m_cRefSamplesDMVRL0[1], pcYuvDst.Cb()), PelBuf(m_cRefSamplesDMVRL0[2], pcYuvDst.Cr())));
02077     m_cYuvRefBuffDMVRL0 = m_cYuvRefBuffDMVRL0.subBuf(UnitAreaRelative(pu, subPu));
02078 
02079     m_cYuvRefBuffDMVRL1 = (pu.chromaFormat == CHROMA_400 ?
02080       PelUnitBuf(pu.chromaFormat, PelBuf(m_cRefSamplesDMVRL1[0], pcYuvDst.Y())) :
02081       PelUnitBuf(pu.chromaFormat, PelBuf(m_cRefSamplesDMVRL1[0], pcYuvDst.Y()), PelBuf(m_cRefSamplesDMVRL1[1], pcYuvDst.Cb()),
02082         PelBuf(m_cRefSamplesDMVRL1[2], pcYuvDst.Cr())));
02083     m_cYuvRefBuffDMVRL1 = m_cYuvRefBuffDMVRL1.subBuf(UnitAreaRelative(pu, subPu));
02084 
02085     PelUnitBuf srcPred0 = (pu.chromaFormat == CHROMA_400 ?
02086       PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[0][0], pcYuvDst.Y())) :
02087       PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[0][0], pcYuvDst.Y()), PelBuf(m_acYuvPred[0][1], pcYuvDst.Cb()), PelBuf(m_acYuvPred[0][2], pcYuvDst.Cr())));
02088     PelUnitBuf srcPred1 = (pu.chromaFormat == CHROMA_400 ?
02089       PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[1][0], pcYuvDst.Y())) :
02090       PelUnitBuf(pu.chromaFormat, PelBuf(m_acYuvPred[1][0], pcYuvDst.Y()), PelBuf(m_acYuvPred[1][1], pcYuvDst.Cb()), PelBuf(m_acYuvPred[1][2], pcYuvDst.Cr())));
02091 
02092     srcPred0 = srcPred0.subBuf(UnitAreaRelative(pu, subPu));
02093     srcPred1 = srcPred1.subBuf(UnitAreaRelative(pu, subPu));
02094 
02095     int yStart = 0;
02096     for (int y = puPos.y; y < (puPos.y + pu.lumaSize().height); y = y + dy, yStart = yStart + dy)
02097     {
02098       for (int x = puPos.x, xStart = 0; x < (puPos.x + pu.lumaSize().width); x = x + dx, xStart = xStart + dx)
02099       {
02100         PredictionUnit subPu = pu;
02101         subPu.UnitArea::operator=(UnitArea(pu.chromaFormat, Area(x, y, dx, dy)));
02102         xPrefetch(subPu, m_cYuvRefBuffDMVRL0, REF_PIC_LIST_0, 1);
02103         xPrefetch(subPu, m_cYuvRefBuffDMVRL1, REF_PIC_LIST_1, 1);
02104 
02105         xinitMC(subPu, clpRngs);
02106 
02107         uint64_t minCost = MAX_UINT64;
02108         bool notZeroCost = true;
02109         int16_t totalDeltaMV[2] = { 0,0 };
02110         int16_t deltaMV[2] = { 0, 0 };
02111         uint64_t  *pSADsArray;
02112         for (int i = 0; i < (((2 * DMVR_NUM_ITERATION) + 1) * ((2 * DMVR_NUM_ITERATION) + 1)); i++)
02113         {
02114           m_SADsArray[i] = MAX_UINT64;
02115         }
02116         pSADsArray = &m_SADsArray[(((2 * DMVR_NUM_ITERATION) + 1) * ((2 * DMVR_NUM_ITERATION) + 1)) >> 1];
02117         for (int i = 0; i < iterationCount; i++)
02118         {
02119           deltaMV[0] = 0;
02120           deltaMV[1] = 0;
02121           Pel *addrL0 = biLinearPredL0 + totalDeltaMV[0] + (totalDeltaMV[1] * m_biLinearBufStride);
02122           Pel *addrL1 = biLinearPredL1 - totalDeltaMV[0] - (totalDeltaMV[1] * m_biLinearBufStride);
02123           if (i == 0)
02124           {
02125             minCost = xDMVRCost(clpRngs.comp[COMPONENT_Y].bd, addrL0, m_biLinearBufStride, addrL1, m_biLinearBufStride, dx, dy);
02126             minCost -= (minCost >>2);
02127             if (minCost < (dx * dy))
02128             {
02129               notZeroCost = false;
02130               break;
02131             }
02132             pSADsArray[0] = minCost;
02133           }
02134           if (!minCost)
02135           {
02136             notZeroCost = false;
02137             break;
02138           }
02139 
02140           xBIPMVRefine(bd, addrL0, addrL1, minCost, deltaMV, pSADsArray, dx, dy);
02141 
02142           if (deltaMV[0] == 0 && deltaMV[1] == 0)
02143           {
02144             break;
02145           }
02146           totalDeltaMV[0] += deltaMV[0];
02147           totalDeltaMV[1] += deltaMV[1];
02148           pSADsArray += ((deltaMV[1] * (((2 * DMVR_NUM_ITERATION) + 1))) + deltaMV[0]);
02149         }
02150 
02151         bioAppliedType[num] = (minCost < bioEnabledThres) ? false : bioApplied;
02152         totalDeltaMV[0] = (totalDeltaMV[0] << mvShift);
02153         totalDeltaMV[1] = (totalDeltaMV[1] << mvShift);
02154         xDMVRSubPixelErrorSurface(notZeroCost, totalDeltaMV, deltaMV, pSADsArray);
02155 
02156         pu.mvdL0SubPu[num] = Mv(totalDeltaMV[0], totalDeltaMV[1]);
02157         PelUnitBuf subPredBuf = pcYuvDst.subBuf(UnitAreaRelative(pu, subPu));
02158 
02159         bool blockMoved = false;
02160         if (pu.mvdL0SubPu[num] != Mv(0, 0))
02161         {
02162           blockMoved = true;
02163           if (isChromaEnabled(pu.chromaFormat))
02164           {
02165           xPrefetch(subPu, m_cYuvRefBuffDMVRL0, REF_PIC_LIST_0, 0);
02166           xPrefetch(subPu, m_cYuvRefBuffDMVRL1, REF_PIC_LIST_1, 0);
02167           }
02168           xPad(subPu, m_cYuvRefBuffDMVRL0, REF_PIC_LIST_0);
02169           xPad(subPu, m_cYuvRefBuffDMVRL1, REF_PIC_LIST_1);
02170         }
02171 
02172         int dstStride[MAX_NUM_COMPONENT] = { pcYuvDst.bufs[COMPONENT_Y].stride,
02173                                              isChromaEnabled(pu.chromaFormat) ? pcYuvDst.bufs[COMPONENT_Cb].stride : 0,
02174                                              isChromaEnabled(pu.chromaFormat) ? pcYuvDst.bufs[COMPONENT_Cr].stride : 0};
02175         subPu.mv[0] = mergeMv[REF_PIC_LIST_0] + pu.mvdL0SubPu[num];
02176         subPu.mv[1] = mergeMv[REF_PIC_LIST_1] - pu.mvdL0SubPu[num];
02177 
02178         subPu.mv[0].clipToStorageBitDepth();
02179         subPu.mv[1].clipToStorageBitDepth();
02180 
02181         xFinalPaddedMCForDMVR(subPu, srcPred0, srcPred1, m_cYuvRefBuffDMVRL0, m_cYuvRefBuffDMVRL1, bioAppliedType[num],
02182                               mergeMv, blockMoved);
02183 
02184         subPredBuf.bufs[COMPONENT_Y].buf = pcYuvDst.bufs[COMPONENT_Y].buf + xStart + yStart * dstStride[COMPONENT_Y];
02185 
02186         if (isChromaEnabled(pu.chromaFormat))
02187         {
02188         subPredBuf.bufs[COMPONENT_Cb].buf = pcYuvDst.bufs[COMPONENT_Cb].buf + (xStart >> scaleX) + ((yStart >> scaleY) * dstStride[COMPONENT_Cb]);
02189 
02190         subPredBuf.bufs[COMPONENT_Cr].buf = pcYuvDst.bufs[COMPONENT_Cr].buf + (xStart >> scaleX) + ((yStart >> scaleY) * dstStride[COMPONENT_Cr]);
02191         }
02192         xWeightedAverage(subPu, srcPred0, srcPred1, subPredBuf, subPu.cu->slice->getSPS()->getBitDepths(), subPu.cu->slice->clpRngs(), bioAppliedType[num]);
02193         num++;
02194       }
02195     }
02196   }
02197   JVET_J0090_SET_CACHE_ENABLE(true);
02198 }
