02200 #if JVET_J0090_MEMORY_BANDWITH_MEASURE
02201 void InterPrediction::cacheAssign( CacheModel *cache )
02202 {
02203   m_cacheModel = cache;
02204   m_if.cacheAssign( cache );
02205   m_if.initInterpolationFilter( !cache->isCacheEnable() );
