02209 void InterPrediction::xFillIBCBuffer(CodingUnit &cu)
02210 {
02211   for (auto &currPU : CU::traverseTUs(cu))
02212   {
02213     for (const CompArea &area : currPU.blocks)
02214     {
02215       if (!area.valid())
02216       {
02217         continue;
02218       }
02219 
02220       const unsigned int lcuWidth = cu.cs->slice->getSPS()->getMaxCUWidth();
02221       const int shiftSampleHor = vtm::getComponentScaleX(area.compID, cu.chromaFormat);
02222       const int shiftSampleVer = vtm::getComponentScaleY(area.compID, cu.chromaFormat);
02223       const int ctuSizeLog2Ver = floorLog2(lcuWidth) - shiftSampleVer;
02224       const int pux = area.x & ((m_IBCBufferWidth >> shiftSampleHor) - 1);
02225       const int puy = area.y & (( 1 << ctuSizeLog2Ver ) - 1);
02226       const CompArea dstArea = CompArea(area.compID, cu.chromaFormat, Position(pux, puy), Size(area.width, area.height));
02227       CPelBuf srcBuf = cu.cs->getRecoBuf(area);
02228       PelBuf dstBuf = m_IBCBuffer.getBuf(dstArea);
02229 
02230       dstBuf.copyFrom(srcBuf);
02231     }
02232   }
02233 }
02234 
02235 void InterPrediction::xIntraBlockCopy(PredictionUnit &pu, PelUnitBuf &predBuf, const ComponentID compID)
02236 {
02237   const unsigned int lcuWidth = pu.cs->slice->getSPS()->getMaxCUWidth();
02238   const int shiftSampleHor = vtm::getComponentScaleX(compID, pu.chromaFormat);
02239   const int shiftSampleVer = vtm::getComponentScaleY(compID, pu.chromaFormat);
02240   const int ctuSizeLog2Ver = floorLog2(lcuWidth) - shiftSampleVer;
02241   pu.bv = pu.mv[REF_PIC_LIST_0];
02242   pu.bv.changePrecision(MV_PRECISION_INTERNAL, MV_PRECISION_INT);
02243   int refx, refy;
02244   if (compID == COMPONENT_Y)
02245   {
02246     refx = pu.Y().x + pu.bv.hor;
02247     refy = pu.Y().y + pu.bv.ver;
02248   }
02249   else
02250   {//Cb or Cr
02251     refx = pu.Cb().x + (pu.bv.hor >> shiftSampleHor);
02252     refy = pu.Cb().y + (pu.bv.ver >> shiftSampleVer);
02253   }
02254   refx &= ((m_IBCBufferWidth >> shiftSampleHor) - 1);
02255   refy &= ((1 << ctuSizeLog2Ver) - 1);
02256 
02257   if (refx + predBuf.bufs[compID].width <= (m_IBCBufferWidth >> shiftSampleHor))
02258   {
02259     const CompArea srcArea = CompArea(compID, pu.chromaFormat, Position(refx, refy), Size(predBuf.bufs[compID].width, predBuf.bufs[compID].height));
02260     const CPelBuf refBuf = m_IBCBuffer.getBuf(srcArea);
02261     predBuf.bufs[compID].copyFrom(refBuf);
02262   }
02263   else
02264   {//wrap around
02265     int width = (m_IBCBufferWidth >> shiftSampleHor) - refx;
02266     CompArea srcArea = CompArea(compID, pu.chromaFormat, Position(refx, refy), Size(width, predBuf.bufs[compID].height));
02267     CPelBuf srcBuf = m_IBCBuffer.getBuf(srcArea);
02268     PelBuf dstBuf = PelBuf(predBuf.bufs[compID].bufAt(Position(0, 0)), predBuf.bufs[compID].stride, Size(width, predBuf.bufs[compID].height));
02269     dstBuf.copyFrom(srcBuf);
02270 
02271     width = refx + predBuf.bufs[compID].width - (m_IBCBufferWidth >> shiftSampleHor);
02272     srcArea = CompArea(compID, pu.chromaFormat, Position(0, refy), Size(width, predBuf.bufs[compID].height));
02273     srcBuf = m_IBCBuffer.getBuf(srcArea);
02274     dstBuf = PelBuf(predBuf.bufs[compID].bufAt(Position((m_IBCBufferWidth >> shiftSampleHor) - refx, 0)), predBuf.bufs[compID].stride, Size(width, predBuf.bufs[compID].height));
02275     dstBuf.copyFrom(srcBuf);
02276   }
02277 }
02278 
02279 void InterPrediction::resetIBCBuffer(const ChromaFormat chromaFormatIDC, const int ctuSize)
02280 {
02281   const UnitArea area = UnitArea(chromaFormatIDC, Area(0, 0, m_IBCBufferWidth, ctuSize));
02282   m_IBCBuffer.getBuf(area).fill(-1);
02283 }
02284 
02285 void InterPrediction::resetVPDUforIBC(const ChromaFormat chromaFormatIDC, const int ctuSize, const int vSize, const int xPos, const int yPos)
02286 {
02287   const UnitArea area = UnitArea(chromaFormatIDC, Area(xPos & (m_IBCBufferWidth - 1), yPos & (ctuSize - 1), vSize, vSize));
02288   m_IBCBuffer.getBuf(area).fill(-1);
02289 }
02290 
02291 bool InterPrediction::isLumaBvValid(const int ctuSize, const int xCb, const int yCb, const int width, const int height, const int xBv, const int yBv)
02292 {
02293   if(((yCb + yBv) & (ctuSize - 1)) + height > ctuSize)
02294   {
02295     return false;
02296   }
02297   int refTLx = xCb + xBv;
02298   int refTLy = (yCb + yBv) & (ctuSize - 1);
02299   PelBuf buf = m_IBCBuffer.Y();
02300   for(int x = 0; x < width; x += 4)
02301   {
02302     for(int y = 0; y < height; y += 4)
02303     {
02304       if(buf.at((x + refTLx) & (m_IBCBufferWidth - 1), y + refTLy) == -1) return false;
02305       if(buf.at((x + 3 + refTLx) & (m_IBCBufferWidth - 1), y + refTLy) == -1) return false;
02306       if(buf.at((x + refTLx) & (m_IBCBufferWidth - 1), y + 3 + refTLy) == -1) return false;
02307       if(buf.at((x + 3 + refTLx) & (m_IBCBufferWidth - 1), y + 3 + refTLy) == -1) return false;
02308     }
02309   }
02310   return true;
02311 }
02312 
02313 bool InterPrediction::xPredInterBlkRPR( const std::pair<int, int>& scalingRatio, const PPS& pps, const CompArea &blk, const Picture* refPic, const Mv& mv, Pel* dst, const int dstStride, const bool bi, const bool wrapRef, const ClpRng& clpRng, const int filterIndex, const bool useAltHpelIf )
02314 {
02315   const ChromaFormat  chFmt = blk.chromaFormat;
02316   const ComponentID compID = blk.compID;
02317   const bool          rndRes = !bi;
02318 
02319   int shiftHor = MV_FRACTIONAL_BITS_INTERNAL + vtm::getComponentScaleX( compID, chFmt );
02320   int shiftVer = MV_FRACTIONAL_BITS_INTERNAL + vtm::getComponentScaleY( compID, chFmt );
02321 
02322   int width = blk.width;
02323   int height = blk.height;
02324   CPelBuf refBuf;
02325 
02326   const bool scaled = refPic->isRefScaled( &pps );
02327 
02328   if( scaled )
02329   {
02330     int row, col;
02331     int refPicWidth = refPic->getPicWidthInLumaSamples();
02332     int refPicHeight = refPic->getPicHeightInLumaSamples();
02333 
02334     int xFilter = filterIndex;
02335     int yFilter = filterIndex;
02336     const int rprThreshold1 = ( 1 << SCALE_RATIO_BITS ) * 5 / 4;
02337     const int rprThreshold2 = ( 1 << SCALE_RATIO_BITS ) * 7 / 4;
02338     if( filterIndex == 0 )
02339     {
02340       if( scalingRatio.first > rprThreshold2 )
02341       {
02342         xFilter = 4;
02343       }
02344       else if( scalingRatio.first > rprThreshold1 )
02345       {
02346         xFilter = 3;
02347       }
02348 
02349       if( scalingRatio.second > rprThreshold2 )
02350       {
02351         yFilter = 4;
02352       }
02353       else if( scalingRatio.second > rprThreshold1 )
02354       {
02355         yFilter = 3;
02356       }
02357     }
02358     if (filterIndex == 2)
02359     {
02360       if (isLuma(compID))
02361       {
02362         if (scalingRatio.first > rprThreshold2)
02363         {
02364           xFilter = 6;
02365         }
02366         else if (scalingRatio.first > rprThreshold1)
02367         {
02368           xFilter = 5;
02369         }
02370 
02371         if (scalingRatio.second > rprThreshold2)
02372         {
02373           yFilter = 6;
02374         }
02375         else if (scalingRatio.second > rprThreshold1)
02376         {
02377           yFilter = 5;
02378         }
02379       }
02380       else
02381       {
02382         if (scalingRatio.first > rprThreshold2)
02383         {
02384           xFilter = 4;
02385         }
02386         else if (scalingRatio.first > rprThreshold1)
02387         {
02388           xFilter = 3;
02389         }
02390 
02391         if (scalingRatio.second > rprThreshold2)
02392         {
02393           yFilter = 4;
02394         }
02395         else if (scalingRatio.second > rprThreshold1)
02396         {
02397           yFilter = 3;
02398         }
02399       }
02400     }
02401 
02402     const int posShift = SCALE_RATIO_BITS - 4;
02403     int stepX = ( scalingRatio.first + 8 ) >> 4;
02404     int stepY = ( scalingRatio.second + 8 ) >> 4;
02405     int64_t x0Int;
02406     int64_t y0Int;
02407     int offX = 1 << ( posShift - shiftHor - 1 );
02408     int offY = 1 << ( posShift - shiftVer - 1 );
02409 
02410     const int64_t posX = ( ( blk.pos().x << vtm::getComponentScaleX( compID, chFmt ) ) - ( pps.getScalingWindow().getWindowLeftOffset() * SPS::getWinUnitX( chFmt ) ) ) >> vtm::getComponentScaleX( compID, chFmt );
02411     const int64_t posY = ( ( blk.pos().y << vtm::getComponentScaleY( compID, chFmt ) ) - ( pps.getScalingWindow().getWindowTopOffset()  * SPS::getWinUnitY( chFmt ) ) ) >> vtm::getComponentScaleY( compID, chFmt );
02412 
02413     int addX = isLuma( compID ) ? 0 : int( 1 - refPic->cs->sps->getHorCollocatedChromaFlag() ) * 8 * ( scalingRatio.first - SCALE_1X.first );
02414     int addY = isLuma( compID ) ? 0 : int( 1 - refPic->cs->sps->getVerCollocatedChromaFlag() ) * 8 * ( scalingRatio.second - SCALE_1X.second );
02415     
02416 #if FIX_SUBPICS_W_RPR
02417     int boundLeft   = 0;
02418     int boundRight  = refPicWidth >> vtm::getComponentScaleX( compID, chFmt );
02419     int boundTop    = 0;
02420     int boundBottom = refPicHeight >> vtm::getComponentScaleY( compID, chFmt );
02421     if( refPic->subPictures.size() > 1 )
02422     {
02423       const SubPic& curSubPic = pps.getSubPicFromPos(blk.lumaPos());
02424       if( curSubPic.getTreatedAsPicFlag() )
02425       {
02426         boundLeft   = curSubPic.getSubPicLeft()   >> vtm::getComponentScaleX( compID, chFmt );
02427         boundRight  = curSubPic.getSubPicRight()  >> vtm::getComponentScaleX( compID, chFmt );
02428         boundTop    = curSubPic.getSubPicTop()    >> vtm::getComponentScaleY( compID, chFmt );
02429         boundBottom = curSubPic.getSubPicBottom() >> vtm::getComponentScaleY( compID, chFmt );
02430       }
02431     }
02432 #endif
02433 
02434     x0Int = ( ( posX << ( 4 + vtm::getComponentScaleX( compID, chFmt ) ) ) + mv.getHor() ) * (int64_t)scalingRatio.first + addX;
02435     x0Int = SIGN( x0Int ) * ( ( llabs( x0Int ) + ( (long long)1 << ( 7 + vtm::getComponentScaleX( compID, chFmt ) ) ) ) >> ( 8 + vtm::getComponentScaleX( compID, chFmt ) ) ) + ( ( refPic->getScalingWindow().getWindowLeftOffset() * SPS::getWinUnitX( chFmt ) ) << ( ( posShift - vtm::getComponentScaleX( compID, chFmt ) ) ) );
02436 
02437     y0Int = ( ( posY << ( 4 + vtm::getComponentScaleY( compID, chFmt ) ) ) + mv.getVer() ) * (int64_t)scalingRatio.second + addY;
02438     y0Int = SIGN( y0Int ) * ( ( llabs( y0Int ) + ( (long long)1 << ( 7 + vtm::getComponentScaleY( compID, chFmt ) ) ) ) >> ( 8 + vtm::getComponentScaleY( compID, chFmt ) ) ) + ( ( refPic->getScalingWindow().getWindowTopOffset() * SPS::getWinUnitY( chFmt ) ) << ( ( posShift - vtm::getComponentScaleY( compID, chFmt ) ) ) );
02439 
02440     const int extSize = isLuma( compID ) ? 1 : 2;
02441     int vFilterSize = isLuma( compID ) ? NTAPS_LUMA : NTAPS_CHROMA;
02442 
02443     int yInt0 = ( (int32_t)y0Int + offY ) >> posShift;
02444 #if FIX_SUBPICS_W_RPR
02445     yInt0 = std::min( std::max( boundTop - (NTAPS_LUMA / 2), yInt0 ), boundBottom + (NTAPS_LUMA / 2) );
02446 #else
02447     yInt0 = std::min( std::max( -(NTAPS_LUMA / 2), yInt0 ), ( refPicHeight >> ::getComponentScaleY( compID, chFmt ) ) + (NTAPS_LUMA / 2) );
02448 #endif
02449 
02450     int xInt0 = ( (int32_t)x0Int + offX ) >> posShift;
02451 #if FIX_SUBPICS_W_RPR
02452     xInt0 = std::min( std::max( boundLeft - (NTAPS_LUMA / 2), xInt0 ), boundRight + (NTAPS_LUMA / 2) );
02453 #else
02454     xInt0 = std::min( std::max( -(NTAPS_LUMA / 2), xInt0 ), ( refPicWidth >> ::getComponentScaleX( compID, chFmt ) ) + (NTAPS_LUMA / 2) );
02455 #endif
02456 
02457     int refHeight = ((((int32_t)y0Int + (height-1) * stepY) + offY ) >> posShift) - ((((int32_t)y0Int + 0 * stepY) + offY ) >> posShift) + 1;
02458     refHeight = std::max<int>( 1, refHeight );
02459 
02460     CHECK( MAX_CU_SIZE * MAX_SCALING_RATIO + 16 < refHeight + vFilterSize - 1 + extSize, "Buffer is not large enough, increase MAX_SCALING_RATIO" );
02461 
02462     Pel buffer[( MAX_CU_SIZE + 16 ) * ( MAX_CU_SIZE * MAX_SCALING_RATIO + 16 )];
02463     int tmpStride = width;
02464     int xInt = 0, yInt = 0;
02465 
02466     for( col = 0; col < width; col++ )
02467     {
02468       int posX = (int32_t)x0Int + col * stepX;
02469       xInt = ( posX + offX ) >> posShift;
02470 #if FIX_SUBPICS_W_RPR
02471       xInt = std::min( std::max( boundLeft - (NTAPS_LUMA / 2), xInt ), boundRight + (NTAPS_LUMA / 2) );
02472 #else
02473       xInt = std::min( std::max( -(NTAPS_LUMA / 2), xInt ), ( refPicWidth >> ::getComponentScaleX( compID, chFmt ) ) + (NTAPS_LUMA / 2) );
02474 #endif
02475       int xFrac = ( ( posX + offX ) >> ( posShift - shiftHor ) ) & ( ( 1 << shiftHor ) - 1 );
02476 
02477       CHECK( xInt0 > xInt, "Wrong horizontal starting point" );
02478 
02479       Position offset = Position( xInt, yInt0 );
02480       refBuf = refPic->getRecoBuf( CompArea( compID, chFmt, offset, Size( 1, refHeight ) ), wrapRef );
02481       Pel* tempBuf = buffer + col;
02482 
02483       m_if.filterHor( compID, (Pel*)refBuf.buf - ( ( vFilterSize >> 1 ) - 1 ) * refBuf.stride, refBuf.stride, tempBuf, tmpStride, 1, refHeight + vFilterSize - 1 + extSize, xFrac, false, chFmt, clpRng, xFilter, false, useAltHpelIf && scalingRatio.first == 1 << SCALE_RATIO_BITS );
02484     }
02485 
02486     for( row = 0; row < height; row++ )
02487     {
02488       int posY = (int32_t)y0Int + row * stepY;
02489       yInt = ( posY + offY ) >> posShift;
02490 #if FIX_SUBPICS_W_RPR
02491       yInt = std::min( std::max( boundTop - (NTAPS_LUMA / 2), yInt ), boundBottom + (NTAPS_LUMA / 2) );
02492 #else
02493       yInt = std::min( std::max( -(NTAPS_LUMA / 2), yInt ), ( refPicHeight >> ::getComponentScaleY( compID, chFmt ) ) + (NTAPS_LUMA / 2) );
02494 #endif
02495       int yFrac = ( ( posY + offY ) >> ( posShift - shiftVer ) ) & ( ( 1 << shiftVer ) - 1 );
02496 
02497       CHECK( yInt0 > yInt, "Wrong vertical starting point" );
02498 
02499       Pel* tempBuf = buffer + ( yInt - yInt0 ) * tmpStride;
02500 
02501       JVET_J0090_SET_CACHE_ENABLE( false );
02502       m_if.filterVer( compID, tempBuf + ( ( vFilterSize >> 1 ) - 1 ) * tmpStride, tmpStride, dst + row * dstStride, dstStride, width, 1, yFrac, false, rndRes, chFmt, clpRng, yFilter, false, useAltHpelIf && scalingRatio.second == 1 << SCALE_RATIO_BITS );
02503       JVET_J0090_SET_CACHE_ENABLE( true );
02504     }
02505   }
02506 
02507   return scaled;
02508 }
02509 
02510 } // namespace vtm
